programs.sol:
"""A surface-word detector centered on 'people', not on every human reference.

It gives a strong negative response to 'people', smaller responses to selected
human nouns and their translations, and echoes the spelling endings 'ople' and
'ple' even in other words. Capitalized 'People' is stronger; quantification
weakens it. 'Of' and possessive endings just after 'people' retain a response.
Everything else is silent. Only the preceding token is remembered, with a
reset at each new document.
"""
READS = ()

# General human nouns and translations, grouped by response strength.
HUMAN_NOUNS = (
    (-2.9, {'folks', '人民'}),
    (-2.35, {'folk', 'peoples', 'ppl', '人们', '人們', 'люди', '人々'}),
    (-1.8, {'menschen', 'mensen', 'pessoas', 'людей', 'الناس'}),
    (-1.3, {'personas', 'personnes', 'persone', 'gente', '群众'}),
    (-1.05, {'staff', 'personnel', 'personne', 'personen',
             '大家', 'คน', '很多人', '百姓', '民眾', '民众'}),
    (-0.85, {'person', 'individuals', 'kids', 'children', 'スタッフ',
             '人員', '工作人员', 'みんな'}),
    (-0.65, {'persons', 'người', 'kişi', '人员', '人士', '人群',
             '的人', 'の人', '人家'}),
    (-0.55, {'women'}),
    (-0.4, {'adults', 'faculty', 'crew', 'audience'}),
)
NUMBERS = {'one', 'two', 'three', 'four', 'five', 'six', 'seven',
           'eight', 'nine', 'ten', 'hundred', 'thousand', 'million'}
QUANTIFIERS = {'some', 'many', 'more', 'other', 'few', 'several'}
DEMONSTRATIVES = {'these', 'those'}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = '' if carry is None or carry[0] != doc else carry[1]
    raw = prefix.token_strings[-1].strip()
    word = raw.lower()
    prev = previous.lower()
    value = 0.0
    if word == 'people':
        value = -5.95 if raw[0].isupper() else -5.32
        if prev.isdigit() or prev in NUMBERS:
            value += 0.8
        elif prev == 'young':
            value += 1.15
        elif prev == 'most':
            value += 0.9
        elif prev in DEMONSTRATIVES:
            value += 0.5
        elif prev in QUANTIFIERS:
            value += 0.3
    else:
        for strength, nouns in HUMAN_NOUNS:
            if word in nouns:
                value = strength
                break
        # The last pieces of the spelling 'people' also fire in other words.
        if word == 'ople':
            value = -2.15
        elif word == 'ple':
            value = -0.65
        if prev == 'people':
            capital = previous[0].isupper()
            if word == 'of':
                value = -1.95 if capital else -1.7
            elif word in {"'s", '’s'}:
                value = -1.05 if capital else -0.7
    return (doc, raw), float(value)

programs.haiku:
"""Fires (negatively) on words for people and groups of people.

This component's activation is mostly a token-identity signal. It goes strongly negative
(about -5.5) on the English word "people" in any case or spacing. It is moderately negative
(about -2) on other words for a crowd of people ("folks", "folk", "peoples", 人民, 人们,
людей, Menschen, personnes, ...), and weakly negative (about -0.8) on words for individuals
and groups of persons ("person", "children", "kids", "staff", "women", "individuals", ...).
Every other token predicts 0. The sign and size are those of the component's activation,
so a large negative value means the component is writing "people-ness" into the residual
stream at that token.

The program looks only at the current token, so the carry is unused.
"""

READS = ()

PEOPLE = {"people"}
CROWD = {
    "folks", "folk", "peoples", "人民", "人们", "大家", "群众", "людей", "люди",
    "menschen", "personnes", "personas", "persone", "gente",
}
PERSONS = {
    "person", "persons", "children", "kids", "individuals", "staff", "personnel",
    "women", "人员", "工作人员", "スタッフ", "人士",
}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    if word in PEOPLE:
        value = -5.5
    elif word in CROWD:
        value = -2.0
    elif word in PERSONS:
        value = -0.8
    else:
        value = 0.0
    return carry, value

programs.sol:
"""Approximate an English linking-word boundary signal.

An isolated preposition/conjunction at document start is strongly positive,
especially space-prefixed 'of' and 'to'. Adjacent linking words are weaker
positives: 'that of', 'how to', 'and in', and preposition + 'that'. Most
other positions are zero. Onsets have small spelling/punctuation offsets.
This deliberately omits the many small, token-specific fluctuations.
"""
READS = ()

PREPOSITIONS = set('''of to in for on with at by from as into about over under
between through after before during without within around across toward towards
against among upon along throughout beyond regarding concerning despite except
per via'''.split())
CONJUNCTIONS = set('and or but nor yet so'.split())
SUBORDINATORS = set('''that if whether because although though while since unless
until when where whereas once than'''.split())
DETERMINERS = set('''the a an this these those any every some each all both
another other no such'''.split())
OTHER_FUNCTION_WORDS = set('''how what which who whom whose why i you he she it
we they me him her us them my your his its our their is am are was were be been
being have has had do does did can could will would shall should may might must
not'''.split())
FUNCTION_WORDS = (PREPOSITIONS | CONJUNCTIONS | SUBORDINATORS | DETERMINERS
                  | OTHER_FUNCTION_WORDS)
LINKS = PREPOSITIONS | SUBORDINATORS | CONJUNCTIONS | {'using'}

# The largest isolated-word responses, within a closed grammatical class.
ISOLATED_LINK_GAINS = {
    'of': 4.18, 'to': 4.27,
    'by': 3.56, 'and': 3.19, 'with': 3.09,
    'in': 2.64, 'for': 2.63, 'from': 2.54, 'or': 2.52,
    'that': 2.47, 'on': 2.28,
}


def onset(s):
    w = s.strip().lower()
    if s == '#':
        return -0.91
    if s in {')', ']', '}'}:
        return 0.69 if s == ')' else 0.36
    if s == ',':
        return 0.32
    if s.strip() in {'(', '"'}:
        return 0.82 if s.startswith(' ') else 0.17
    if s == ' ' + w:
        if w in ISOLATED_LINK_GAINS:
            return ISOLATED_LINK_GAINS[w]
        if w in PREPOSITIONS or w == 'where':
            return 1.35
        if w in {'the', 'a', 'if'}:
            return 1.0
        if w in FUNCTION_WORDS:
            return 0.7
    if w in FUNCTION_WORDS:
        return 0.52 if s[:1].isupper() else 0.36
    if s.strip().isalpha():
        if s.strip()[0].isupper():
            return 0.17
        return 0.32 if s.startswith(' ') else 0.16
    return 0.13


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        return (doc, s, 0), float(onset(s))
    _, previous, position = carry
    w, prev = s.strip().lower(), previous.strip().lower()
    # Don't mistake a suffix (the 'or' in 'traitor') for a linking word.
    if not previous.startswith(' ') and position != 0:
        prev = ''
    position += 1
    value = 0.0
    if s == ' ' + w and w in LINKS:
        if w == 'of' and prev == 'that':
            value = 2.0
        elif w == 'to' and prev == 'how':
            value = 0.93
        elif (prev in {'and', 'or', 'that'}
              and w in PREPOSITIONS | {'that', 'using'}):
            value = 1.1 if w in {'to', 'of'} else 0.68
        elif w == 'that' and prev in PREPOSITIONS | {'but', 'than'}:
            value = 0.49
        elif (prev in PREPOSITIONS | {'than', 'when', 'where', 'while', 'if', 'but'}
              and w in PREPOSITIONS | {'using'}):
            value = 0.48
        elif w == 'and' and prev in PREPOSITIONS:
            value = 0.4
        elif prev in {'not', 'also', 'then', 'those', 'which'}:
            value = 0.28
        elif w in {'throughout', 'regarding', 'concerning'}:
            value = 0.26
        elif w in {'about', 'around', 'though', 'although'}:
            value = 0.12
        elif w == 'using':
            value = 0.08
    if previous.strip() != previous.strip().lower():
        value *= 0.4
    if position < 4:
        value += 0.03 / position
    return (doc, s, position), float(value)

programs.haiku:
"""Layer-0 feature that fires on function words (prepositions, conjunctions, articles)
that come with little or no preceding context.

- At the start of a document (or of a packed row), the model has no earlier words to
  read, and the first word is a bare preposition or conjunction ("to", "of", "and",
  "with", ...): the feature is strongly positive. Articles are weaker; other lowercase
  words are barely positive.
- Mid-document, a preposition or conjunction that directly follows another function
  word, especially "how to", "that of", "than that", "and to", "or in", is positive.
  After a content word ("used for", "required to") it is about zero.
Everything else is zero. Activations are in the component's own units.
"""
READS = ()

PREPOSITIONS = {" to", " of", " by", " with", " in", " for", " from", " on", " into", " at",
                " as", " about", " between", " than", " after", " before", " over", " under"}
CONJUNCTIONS = {" and", " or", " that", " but", " which", " when", " if", " while", " because"}
ARTICLES = {" the", " a", " an", " this", " these", " those", " its", " their", " his", " her"}
FUNCTION_WORDS = PREPOSITIONS | CONJUNCTIONS | ARTICLES | {" how", " it", " is", " not", " no", " what", " who", " where", " there", " can", " will", " should", " may", " also"}
# words after which a preposition/conjunction is especially positive
STRONG_PREVIOUS = {" how", " than", " that", " those", " and", " or", " to", " as", " with", " when", " if", " which"}


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    new_doc = prefix.position == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]
    if new_doc:
        if tok in PREPOSITIONS:
            return None, 3.0
        if tok in CONJUNCTIONS:
            return None, 2.5
        if tok in ARTICLES:
            return None, 1.0
        if tok[:1] == " " and tok[1:].isalpha() and tok[1:].islower():
            return None, 0.4
        return None, 0.0
    if tok in PREPOSITIONS or tok in CONJUNCTIONS:
        prev = prefix.token_strings[-2]
        if prev in STRONG_PREVIOUS:
            return None, 0.6
        if prev in FUNCTION_WORDS:
            return None, 0.15
    return None, 0.0

programs.luna:
"""A stronger pulse for common English function words at document boundaries."""
READS = ()

COMMON_FUNCTION_WORDS = {
    "the", "we", "was", "to", "of", "in", "on",
}

def step(carry, prefix, upstream):
    docs = prefix.document_ids
    first = len(docs) == 1 or docs[-1] != docs[-2]
    if not first:
        return None, 0.0
    word = prefix.token_strings[-1].strip().lower()
    return None, 0.65 if word in COMMON_FUNCTION_WORDS else 0.1

programs.sol:
"""Predict a strong 'what/whatever' response and weaker referring-word responses.

Read only the current and preceding token. Capitalization, attached punctuation,
and immediate grammatical cues change the strength. In particular, 'that'
after statement-introducing verbs/adjectives is suppressed, while 'how many'
and 'how much' are positive. A few foreign equivalents are recognized too.
This is a surface approximation, not a parser; unrecognized tokens give zero.
"""
READS = ()

# Verbs commonly followed by a statement introduced with 'that'.
CLAUSE_VERBS = set('''
know think believe suppose assume say state report mention note suggest show
find observe indicate reveal demonstrate prove ensure conclude mean claim
argue explain confirm recognize realize understand hope expect predict agree
admit remember determine see notice imply require seem consider discover
'''.split())
for verb in tuple(CLAUSE_VERBS):
    stem = verb[:-1] if verb.endswith('e') else verb
    CLAUSE_VERBS.update((verb + 's', stem + 'ed', stem + 'ing'))
    if verb.endswith('y'):
        CLAUSE_VERBS.update((verb[:-1] + 'ies', verb[:-1] + 'ied'))
CLAUSE_VERBS.update('''
knew thought said showed shown found meant understood seen known felt told
admitted agreed noting assuming indicating ensuring stating
'''.split())
CLAUSE_ADJECTIVES = set('''
clear possible likely unlikely important evident true apparent obvious
probable necessary confident certain sure
'''.split())
LINKING_WORDS = set('and but or in of for to at with than from on as by'.split())
KNOWING = set('know knowing knew learn learned find determine'.split())
CHECKING = set('see check discover understand asking asked'.split())

# Lowercase and capitalized strengths for weaker members of the family.
REFERRING_WORDS = {
    'same': (0.75, 0.75), 'such': (1.02, 0.90),
    'whose': (0.68, 0.68), 'whom': (0.52, 0.52),
    'where': (0.20, 0.20), 'when': (-0.10, -0.10),
    'how': (-0.24, 0.33), 'why': (-0.18, 0.65), 'who': (0.03, 0.42),
    'whichever': (2.1, 2.1), 'whatsoever': (2.4, 2.4),
}
TRANSLATIONS = {
    'que': 0.29, 'che': 0.49, 'qué': 0.9, 'что': 0.24,
    'gì': 1.4, 'hvad': 1.7, 'welche': 0.66, '何': 0.95,
}


def response(token, previous, first):
    spelling = token.strip()
    word, before = spelling.lower(), previous.strip().lower()
    capital = spelling[:1].isupper()
    if word == 'whatever':
        return 4.9 if capital else 5.65
    if word == 'what':
        if first and spelling == 'What':
            return 12.05
        value = 5.95 if capital or not token.startswith(' ') else 6.7
        if before in KNOWING:
            value += 1.25
        elif before in CHECKING:
            value += 0.65
        elif before in {'at', 'under', 'exactly'}:
            value -= 1.0
        elif before in {'of', 'to', 'and', 'but', 'so'} or ',' in before:
            value -= 0.55
        elif '#' in before:
            value += 0.7
        return value
    if spelling.lstrip('"\'“‘([{.').lower() == 'what':
        return 5.15 if any(c.isupper() for c in spelling) else 5.6
    if word == 'which':
        if capital:
            return 1.45
        if before in {'in', 'at', 'after', 'during'}:
            return 0.52
        if before in {'to', 'for', 'from', 'by', 'with', 'through', 'under'}:
            return 0.76
        return 0.96 if before == 'of' else 1.23
    if word == 'that':
        if capital:
            return 0.58
        if before in CLAUSE_VERBS | CLAUSE_ADJECTIVES | {'fact', 'such'}:
            return -0.12
        if before in {'is', 'are', 'was', 'were', 'be', 'been', 'so',
                      'not', 'just', 'except', 'out'}:
            return 0.02
        if before in LINKING_WORDS:
            return 0.27
        return 0.38 if ',' in previous else 0.45
    if word == 'one':
        if capital:
            return 1.02
        if before in {'no', 'least'}:
            return 0.20
        if before in {'only', 'any', 'some', 'every', 'exactly'}:
            return 0.48
        # Distinguish standalone 'one' from a suffix inside a longer word.
        return 0.25 if token == spelling and previous[-1:].isalpha() else 0.86
    if word in {'many', 'much'} and before == 'how':
        return 1.10 if word == 'many' else 0.90
    for pronoun, strength in [('什么', 3.3), ('什麼', 2.5), ('什麽', 2.3)]:
        if spelling == pronoun:
            return strength
        if (spelling.endswith(pronoun) and not
                spelling.endswith(('为什么', '為什麼', '為什麽'))):
            return strength * 0.8
    if word in REFERRING_WORDS:
        return REFERRING_WORDS[word][int(capital)]
    if word == 'ما':
        return 1.6 if token.startswith(' ') else 0.76
    if word in {'que', 'che'} and token == spelling and previous[-1:].isalpha():
        return 0.0
    return TRANSLATIONS.get(word, 0.0)


def step(carry, prefix, upstream):
    first = (prefix.position == 0 or
             prefix.document_ids[-1] != prefix.document_ids[-2])
    previous = '' if first else prefix.token_strings[-2]
    return None, float(response(prefix.token_strings[-1], previous, first))

programs.haiku:
"""Wh-words: the component fires on the word "what" and on a few related words.

Its biggest response is to "what" in any capitalisation ("what", "What", "whatever"):
about 6-7 nats of activation, and about 8 right after a verb of knowing or showing
("you know what", "show what", "find out what"). Weaker responses, roughly 0.5-1.2,
come on "which", "such", "one", "same", "whose" and "whom". "that" responds only
when it introduces a relative clause (after a noun or comma), not after verbs like
"know" or "say", where it is near zero. Everything else is near zero.
"""

READS = ()

WHAT_WORDS = {"what", "whatever", "whatsoever", "whats"}
KNOW_VERBS = {"know", "see", "show", "out", "understand", "check", "discover", "tell", "learn"}
WEAK = {"which": 1.1, "such": 1.0, "one": 0.8, "same": 0.7, "whose": 0.7, "whom": 0.5}
NON_RELATIVE_BEFORE = {"is", "so", "such", "know", "say", "said", "means", "suggest",
                       "suggests", "show", "shows", "found", "think", "note", "ensure", "fact"}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().strip('"“”').lower()
    before = prefix.token_strings[-2].strip().lower() if len(prefix) > 1 else ""
    if word in WHAT_WORDS:
        return carry, 8.0 if before in KNOW_VERBS else 6.5
    if word == "that":
        return carry, 0.0 if before in NON_RELATIVE_BEFORE else 0.4
    return carry, WEAK.get(word, 0.0)

programs.sol:
"""Pulses for chat/section boundaries, doubled backslashes and 'et al.'

Closing a chat turn gives the strongest dialogue pulse; opening one is
weaker. These pulses grow toward a ceiling as the document gets longer,
except that its first chat opener is nearly silent. Tool/reasoning section
boundaries have smaller pulses. Doubled backslashes and the citation
abbreviation 'et al.' are additional triggers. Chat role labels get small
adjustments, especially at document start; other text stays near zero.
"""

import re

READS = ()

# For each real section marker: ceiling, early-document deficit, offset, power.
SECTIONS = {
    '<tool_call>': (0.88, 0.33, 1, 0.3),
    '</tool_call>': (1.71, 1.54, 1, 1.0),
    '<tool_response>': (0.994, 0.87, 2, 0.5),
    '</tool_response>': (1.43, 3.50, 3, 1.0),
    '<think>': (0.93, 0.82, 1, 0.6),
    '</think>': (0.50, 0.65, 1, 0.4),
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        position, previous, before_previous = 0, '', ''
    else:
        _, position, previous, before_previous = carry
    token = prefix.token_strings[-1]
    value = 0.0
    if token == '<|im_end|>':
        value = 0.62 if position == 0 else 2.29 - 2.61 / (position + 2)**0.7
        if previous == '</tool_response>':
            value -= 0.27
        elif previous == '</tool_call>':
            value -= 0.19
    elif token == '<|im_start|>':
        value = 0.027 if position == 0 else 1.08 - 4.40 / (position + 8)
    elif token in SECTIONS:
        ceiling, deficit, offset, power = SECTIONS[token]
        value = max(0.0, ceiling - deficit / (position + offset)**power)
        if token == '<tool_call>' and previous == '\n':
            value -= 0.065
    elif previous == '<|im_start|>' and token in ('user', 'assistant', 'system'):
        if position == 1:
            value = {'user': 0.178, 'assistant': 0.052, 'system': 0.475}[token]
        else:
            value = -0.092 if token == 'user' else 0.009
    elif '\\\\' in token:
        run = max(len(m.group()) for m in re.finditer(r'\\+', token))
        if run >= 4:
            value = 2.25
        elif run % 2 or token.endswith(('.', '"', '\n')):
            value = 1.08
        else:
            value = 1.88 - 0.17 * token.startswith(' ')
    elif token == ' al':
        if previous == ' et':
            value = 0.965
        elif previous == 'et':
            value = 0.40
    elif token == '.,' and previous == ' al' and before_previous.strip() == 'et':
        value = 0.16
    return (doc, position + 1, token, previous), float(value)

"""A capitalized-abbreviation/identifier edge signal.
Spaces and parentheses after capital fragments are strongly positive; short
letter extensions joined by hyphens or underscores are negative. Letter-run
length, mixed-case abbreviations, and whether a final letter belongs to a
longer initialism set the strength. Also recognize technical naming nouns,
the stand verb family and 'stand(s) for', and HTTP protocol/version slashes.
This is an approximation: most ordinary tokens return zero.
"""
import re
READS = ()

# One, two, three, or four-plus capital letters in the preceding fragment.
BOUNDARY = {
    ' ': (0.46, 0.82, 0.78, 0.52),
    '(': (0.40, 1.05, 0.90, 0.65),
    ')': (0.31, 0.86, 0.68, 0.30),
    '_': (0.17, 0.28, 0.32, 0.67),
    '=': (0.12, 0.28, 0.25, 0.23),
    '/': (0.15, 0.32, 0.36, 0.24),
}
TECHNICAL_NOUNS = {
    'format', 'file', 'code', 'program', 'function', 'analysis', 'gate',
}
STAND_FORMS = {
    ' stand': 0.65, ' stands': 0.76, ' standing': 0.18,
    ' stood': 0.26, ' Stand': 0.29,
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    word, previous = carry[1:] if carry and carry[0] == doc else ('', '')
    token = prefix.token_strings[-1]
    letters = ''.join(c for c in previous.strip() if c.isalpha())
    n = min(len(letters), 4) if letters.isupper() else 0
    capitals = sum(c.isupper() for c in word)
    mixed_abbreviation = word.isalpha() and capitals >= 2 and capitals * 2 >= len(word)
    split = bool(previous) and not previous[0].isspace()
    strength = (0.45, 1.0, 0.8, 0.4)[n-1] if n else 0.0
    mark = {' (': '(', '（': '(', '）': ')', ' =': '='}.get(token, token)
    value = 0.0
    if token == '/' and word in ('HTTP', 'HTTPS'):
        value = 0.65
    elif mark in BOUNDARY:
        if n:
            value = BOUNDARY[mark][n-1]
            if n == 1 and len(word) > 1 and word.isupper():
                value += {' ': 0.25, '(': 0.45 if token == ' (' else 0.24,
                          ')': 0.43, '/': 0.06}.get(mark, 0.0)
        elif mixed_abbreviation and mark in (' ', '(', ')'):
            value = 0.39 if mark == ' ' else 0.20 if token == '(' else 0.51
        elif letters:
            if mark == ')':
                value = 0.10 if split else 0.04
                if word.endswith('s') and word[:-1].isupper():
                    value = 0.59
            elif mark == '(':
                value = 0.07 if split or letters.istitle() else 0.0
            elif mark == ' ' and split and letters.islower():
                value = 0.09
            elif mark == '_':
                value = 0.08
            if letters[-1].isupper():
                value = {' ': 0.50, '(': 0.60, ')': 0.43}.get(mark, value)
    elif token in STAND_FORMS:
        value = STAND_FORMS[token] + 0.4 * bool(n)
    elif token == ' for' and word in ('stand', 'stands', 'stood', 'standing'):
        value = 0.55
    elif token.strip() in TECHNICAL_NOUNS:
        value = 0.03 + 0.36 * strength
    elif token == 's':
        value = 0.39 if n in (2, 3) else -0.05 if not letters else 0.0
    elif n:
        if len(token) > 1 and token[0] in '-_.' and token[1:].isalpha():
            if token[0] == '-' and len(token) <= 3:
                value = -0.75 * strength
            elif token[0] == '_' and len(token) <= 3:
                value = -0.40 * strength
            elif token[0] == '_' and token[1:].isupper():
                value = 0.03
            else:
                value = -0.14 * strength
        elif token.startswith(')'):
            value = 0.18 * strength
        elif token.startswith('('):
            value = 0.12 * strength
        elif token.startswith(' ') and token.strip().isupper():
            value = (-0.25 if len(token.strip()) <= 2 else -0.06) * strength
        else:
            if n == 1 and word.isupper() and len(word) > 1:
                strength = 0.9
            value = strength * {
                ']': 0.30, '}': 0.30, ' [': 0.30,
                ' in': -0.16, ' to': -0.16, "'s": -0.16, '’s': -0.16,
            }.get(token, 0.0)
    match = re.search(r'\w+$', word + token)
    word = match.group()[-40:] if match else ''
    return (doc, word, token), float(value)

programs.haiku:
"""Layer-0 MLP neuron 1095 (down_proj): fires on the token just after an acronym.

Its activation is large and positive on the token right after an all-caps
abbreviation when that token is a bracket, a space or an underscore:
"Cosmic Scientific Empire (CSE )", "Republican Fascist Party (PFR )",
"NAME_1". It is strongly negative when the abbreviation goes on with a
hyphenated capital piece ("SDS" then "-P"). A single capital letter before
the token gives a weaker version of the same pattern. The word "stand" also
gives a moderate positive value. Everything else is close to zero.
The program remembers only the previous token, and resets at document ends.
"""

import re

ACRONYM = re.compile(r"\s?[A-Z]{2,}")  # all-caps piece of a word: "CSE", " NAME"
CAPITAL = re.compile(r"\s?[A-Z]")  # single capital letter: "S", " C"
HYPHEN_CAPS = re.compile(r"-[A-Z]+")  # hyphen plus capitals: "-L", "-SDS"
OPENERS = {" (", "(", "（"}
CLOSERS = {")", "）", " ", "_"}
PLURAL = {"s", "/"}  # plural 's' or slash directly after an acronym
STAND = {" stand", " stands"}

READS: tuple[str, ...] = ()


def step(carry, prefix, upstream):
    cur = prefix.token_strings[-1]
    same_doc = len(prefix) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    prev = prefix.token_strings[-2] if same_doc else ""
    value = 0.0
    if ACRONYM.fullmatch(prev):
        if cur in OPENERS:
            value = 1.0
        elif cur in CLOSERS:
            value = 0.75
        elif cur in PLURAL:
            value = 0.4
        elif HYPHEN_CAPS.fullmatch(cur):
            value = -0.8
    elif CAPITAL.fullmatch(prev):
        if cur in OPENERS or cur in CLOSERS:
            value = 0.45
        elif HYPHEN_CAPS.fullmatch(cur):
            value = -0.35
    if cur in STAND:
        value = 0.7
    return carry, float(value)

programs.luna:
"""Estimate responses at the close of a parenthesized short label."""
READS = ()


def step(carry, prefix, upstream):
    if prefix.token_strings[-1] != ")":
        return None, 0.0
    before = "".join(prefix.token_strings[max(0, len(prefix.token_strings) - 14):-1])
    if "(" not in before:
        return None, 0.0
    label = "".join(before.rsplit("(", 1)[-1].split())
    if label.endswith("s") and label[:-1].isupper():
        label = label[:-1]
    letters = sum(ch.isalpha() for ch in label)
    if 2 <= letters <= 10 and label.isupper():
        return None, 0.45
    return None, 0.0

programs.sol:
"""A lexical desire/preference pulse, with short grammatical continuations.

Wanting and wishing are strongest. 'Would like' is stronger than ordinary
liking or comparison. Positive feelings and willingness have smaller pulses.
A small multilingual vocabulary covers the same concepts. 'To', articles,
and a few other continuation tokens retain part of the preceding pulse.
Other tokens normally receive zero; no attempt is made to model the many small,
word-specific background activations. Capitalized or unspaced core English
desire tokens have attenuated pulses. Local phrase history resets at document
changes, punctuation, and newlines. Negated desire words also fire. Coefficients are approximate
training measurements, not semantic truth values.
"""
READS = ()

# (pulse on the word, pulse on its following infinitive 'to')
DESIRE = {
    'want': (-4.1, -2.25), 'wants': (-3.4, -2.4),
    'wanted': (-4.0, -1.8), 'wanting': (-2.85, -1.95),
    'wish': (-5.4, -3.7), 'wishes': (-4.7, -2.65),
    'wished': (-6.0, -3.35), 'wishing': (-3.9, -2.5),
    'desire': (-3.0, -2.1), 'desires': (-3.3, -1.6),
    'desired': (-3.35, -1.7), 'desirable': (-2.65, -1.45),
    'prefer': (-2.6, -2.6), 'preferred': (-1.5, -1.2),
}
# Familiar word classes, grouped by the rough size of their response.
CLASSES = (
    (-2.7, 'undesirable'),
    (-2.2, 'willing unwilling reluctant eager interested regret unwanted '
           'unpleasant unhappy'),
    (-1.5, 'happy glad curious preferences grateful delighted thrilled '
           'willingness happier voluntarily'),
    (-1.2, 'likes liked preference preferable pleasure pleased dislike'),
    (-0.9, 'enjoy enjoys enjoying hope hopes hoping hoped joy welcome '
           'appreciate lucky lovely nice wonder wondering convenient '
           'enjoyable enjoyment joyful happily refuse refusal'),
    (-0.6, 'love loves enjoyed preferably intended intent interest interests '
           'goal goals proud believe ambitions ambitious volunteers'),
    (-8.0, '愿 願 不愿'),
    (-5.8, '愿意 不愿意'),
    (-4.3, '希望 我希望 也希望 自愿 願意 愿望 意愿 muốn'),
    (-2.6, '想要 不想 我不想 欲 欲望 心愿 乐 樂'),
    (-2.2, 'жел хот хочу хотите désir souha möchte 想知道'),
    (-1.75, '喜欢 喜歡 楽 快乐 快樂 愉快'),
    (-1.4, '想 我想 你想 兴趣 したい 欲しい ほしい thích'),
    (-1.0, '好き 好きな たい 祝 望 期待 бы pref'),
)
WORDS = {word: value for value, words in CLASSES for word in words.split()}
SUBJECTS = {'i', 'you', 'we', 'he', 'she', 'they'}
WOULD = {'would', "'d", '’d', 'wouldn'}
LEXICAL_TRIGGERS = DESIRE.keys() | WORDS.keys() | {'like'}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        recent, last_value = (), 0.0
    else:
        recent, last_value = carry[1:]
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    prev = recent[-1] if recent else ''
    distance = next((i + 1 for i, w in enumerate(reversed(recent))
                     if w in WOULD), 0)
    value = WORDS.get(word, 0.0)

    if word in DESIRE:
        value = DESIRE[word][0]
        if word in {'want', 'wish'}:
            if prev in {'to', 'the', 'a', 'my', 'his', 'her', 'their', 'for', ','}:
                value *= 0.75
            if prev in {'you', 'we'}:
                value -= 0.7
            if distance:
                value -= 2.5
        elif word in {'prefer', 'preferred'} and distance:
            value -= 2.2
        if token.strip()[:1].isupper() or not token.startswith(' '):
            value *= 0.8
    elif word == 'like':
        if prev == 'something':
            value = 0.8
        elif prev in {'look', 'looks', 'looking'}:
            value = -0.5 if distance else 0.3
        elif distance == 1:
            value = -5.7
        elif distance == 2 and prev in SUBJECTS:
            value = -4.8
        elif distance:
            value = -2.8
        elif prev in SUBJECTS | {"'t", '’t', 'not', 'really', 'also'}:
            value = -1.3
        elif prev in {'feel', 'feels', 'felt'}:
            value = -0.7
        else:
            value = -0.15
    elif word == 'love' and distance:
        value = -2.9
    elif word == 'happy' and distance:
        value = -2.2
    elif word == 'rather':
        value = -3.1 if distance else -0.45
    elif word == 'to':
        if prev in DESIRE:
            value = DESIRE[prev][1] - (0.5 if distance else 0.0)
        elif prev == 'like':
            value = -2.8 if last_value < -3.0 else -1.4
        elif prev == 'happy':
            value = -2.1
        elif prev in WORDS and last_value < -0.5:
            value = min(-1.0, 0.7 * last_value)
    elif word == 'in' and prev in {'interested', 'interest'}:
        value = -1.5 if prev == 'interested' else -0.5
    elif last_value < -1.0 and prev in LEXICAL_TRIGGERS:
        if word in {'the', 'for'}:
            value = 0.35 * last_value
        elif word in {'a', 'an', 'this', 'my', 'your', 'our', 'his', 'her', 'their'}:
            value = 0.17 * last_value
        elif word in {'that', 'it'}:
            value = 0.23 * last_value
        elif word == 'of':
            value = 0.5 * last_value
        elif word in {'ing', 'ful', 'ness', 'ably', 'い'}:
            value = 0.4 * last_value
    if word in WOULD:
        value = -0.08 if word == 'would' else -0.25
    recent = (recent + (word,))[-3:]
    if any(c in token for c in '.!?;\n'):
        recent = ()
    return (doc, recent, value), float(value)

"""A lexical URL-name detector, with smaller responses to related web terms.

This detects the name 'URL', not an address's contents. Case, plurals and
attached code punctuation adjust its negative amplitude. URL-bearing compound
identifiers are weaker. Curl/hurl words are spelling-related spillover.
The response also follows an immediately attached plural or -ing/-y ending,
and a colon labeling a URL. This one-token memory resets at document boundaries.
Other tokens receive zero.
"""
READS = ()

RELATED_WORDS = {
    'uri': -1.8,
    'href': -1.5,
    'permalink': -1.5,
    'fetch': -0.6,
    '网址': -3.7,
    '地址': -1.1,
    '网站': -0.35,
    '链接': -0.6,
    'curl': -3.8,
    'curls': -2.5,
    'curled': -2.5,
    'curly': -1.1,
    'hurl': -1.8,
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    text = token.strip()
    word = text.lstrip("._-(:/\\'\"=$?[,{")
    low = word.lower()
    if low in {'url', 'urls'}:
        value = -6.5 if low == 'urls' and word != 'Urls' else -7.4
        if text.startswith('_'):
            value = -6.25
        elif text.startswith('.URL'):
            value = -9.0
        elif text.startswith('.url'):
            value = -6.4
        elif text.startswith('('):
            value = -6.8
    elif low in RELATED_WORDS:
        value = RELATED_WORDS[low]
    elif low.endswith('baseurl'):
        value = -3.4
    elif low.startswith('urlparse'):
        value = -3.2
    elif low.startswith('urllib'):
        value = -1.3
    elif 'Url' in word or 'URL' in word:
        value = -2.8
    elif low.startswith('url'):
        value = -2.0
    else:
        value = 0.0
    # CURL/HURL split across tokens are weaker than a standalone URL name.
    if token in {'url', 'URL'} and previous.endswith(('C', 'H')):
        value = -5.5
    elif previous.lower().endswith('url'):
        if token in {'s', 'S'}:
            value = -3.5
        elif token == 'ing':
            value = -1.3
        elif token in {'y', 'Y'}:
            value = -0.55
        elif token == ':':
            value = -0.3
    return (doc, word), value

programs.haiku:
"""URL-token detector (negative).

The component writes a strong negative value into the residual stream whenever
the current token is the word "URL" (or a piece of it: "url", "Url", "_url",
" URL", "(url", "BaseUrl"), and a weaker one for related web-address words:
"curl", "URI", "href", the Chinese word for website/URL (网址). Everywhere else it
is close to zero. The program just looks at the current token's text.
"""

import re

READS = ()


def _value(token):
    s = token.lower()
    word = s.lstrip(" _(.-/\t\"'[{")  # the word part of the token
    if re.match(r"url", word):
        return -7.0  # url, urls, urlconnection, ...
    if "网址" in s:
        return -3.6  # Chinese: website address
    if re.match(r"curl(?!y)", word):
        return -4.0  # curl (the command), a different word from URL
    if "url" in s:
        return -3.5  # e.g. BaseUrl
    if re.fullmatch(r"uris?", word):
        return -1.8  # URI
    if re.match(r"href|permalink", word):
        return -1.5  # HTML href, permalink
    return 0.0


def step(carry, prefix, upstream):
    return carry, _value(prefix.token_strings[-1])

