    if text in {'清新', '清爽', '清香', '清净', '清明'}:
        return 2.8
    if text in {'清洗', '清扫', '澄清'}:
        return 0.85
    if text in {'清洁', '清除', '清晨'}:
        return 1.4
    if '清' in text:
        return 0.7 if len(text) > 3 else 2.3
    if text == '明':
        return 0.3 if previous.endswith(('説', '说', '說')) else 1.65
    if text in {'明朝', '明代', '明晰'}:
        return 2.2
    if text in {'明确', '明確', '不明', '分明'}:
        return 1.2
    if text in {'明白', '明朗', '明らか', '明知'}:
        return 0.8
    if text in {'干净', '乾淨', '净', '淨'}:
