    if word == 'ming' and text[0].isupper():
        return 0.8
    if word == 'rõ':
        return 2.0
    if word == 'clear':
        if text.isupper() or text.startswith(('.', '_')):
            return 1.75
        return 2.3 if token.startswith(' ') or text[0].isupper() else 2.0
    if word in {'cleared', 'clearing', 'clearer', 'clears', 'clearest'}:
        return 1.7 if word == 'cleared' else 1.95
    if word in {'clearly', 'unclear', 'clearance', 'clearances'}:
