"""Clarity / cleanliness word detector (layer 0, MLP down-projection feature 1098).

This feature is a "clear / clean" lexical detector. It fires on the token that carries the
idea of clearness or cleanliness: English "clear", "clearer", "cleared", "clearance",
"clearly", "unclear"; "clean", "cleaning", "clarify", "clarity"; Chinese 清 (clear, clean,
pure) and its compounds 清楚 / 清晰 / 不清, and 明 in senses such as 明确 / 明白 (clear,
plain); Vietnamese "rõ" (clear). It is almost silent on every other token. Its
strength depends on the word, not on the context: the same word gets nearly the same
value wherever it appears.

The program reads only the newest token. It predicts the feature's strength for that
token from the word class, and 0 elsewhere.
"""

import re

READS = ()


def strength(token):
    w = token.strip().lower()
    if w == "清":
        return 7.0
    if "清" in w:
        return 3.0
    if w in ("明", "明确", "明白", "明亮", "不明", "分明"):
        return 1.2
    if re.search(r"(^|\W)(un)?clear(er|ed|ing|ance|s)?($|\W)", w):
        return 2.2
    if re.search(r"(^|\W)clearly", w):
        return 1.4
    if re.search(r"(^|\W)clean", w):
        return 1.1
    if re.search(r"(^|\W)clarif|(^|\W)clarit", w):
        return 1.0
    if w == "rõ":
        return 2.0
    return 0.0

def step(carry, prefix, upstream):
    return None, float(strength(prefix.token_strings[-1]))

