"""A spelling-based approximation for short b-, c-, and d-led fragments.

Two-letter Latin fragments give negative values, especially d followed by a
consonant (as in differential notation, abbreviations, or word fragments).
Ordinary vowel syllables and familiar consonant combinations are much weaker.
The rules below group endings rather than memorize token identities. Initial
capitalization, spacing, and attached punctuation soften d-clusters; inverse
centimetres are stronger. Longer d-led words receive only a small negative bias.
This is not a semantic detector and does not reproduce all contextual variation.
"""

READS = ()


def cluster_value(text):
    word = text.strip().lstrip('(_./-')
    if not word or not word.isascii() or not word.isalpha():
        return -0.0013
    if len(word) != 2:
        return -0.033 if word[0].lower() == 'd' else -0.0013

    first, last = word.lower()
    if first == 'd':
        if last in 'tz':
            value = -1.38
        elif last in 'mpvwxy':
            value = -1.12
        elif last in 'fghklnr':
            value = -0.85
        elif last in 'cjs':
            value = -0.62
        elif last in 'bdu':
            value = -0.26
        else:
            value = -0.015
    elif first == 'b':
        if last in 'fmptvwx':
            value = -0.74
        elif last in 'cdghjn':
            value = -0.40
        elif last in 'lsu':
            value = -0.11
        else:
            value = -0.006
    elif first == 'c':
        if last in 'fjmpz':
            value = -0.60
        elif last in 'bgnvy':
            value = -0.31
        elif last in 'krst':
            value = -0.11
        else:
            value = -0.012
    else:
        return -0.0013

    if value < -0.30:
        if word[0].isupper() and word[1].islower():
            value += 0.22 + (0.33 if first == 'd' else 0.0)
        if first == 'd':
            if word.isupper():
                value += 0.13
            if text[0].isspace():
                value += 0.07
            if text.strip()[0] in '(_./-':
                value += 0.22
