"""A coordination pulse: English 'and' after words, weaker after delimiters.

'or' is lower or negative in the same contexts. Nearby 'between', 'both',
and 'either' suppress the expected conjunction, fading over 10--14 tokens.
Capitalized/attached forms and listed foreign conjunctions get separate,
smaller responses. Other tokens predict zero; document boundaries reset state.
This describes the coordination pulses, not small word-specific fluctuations.
"""
READS = ()

# Written forms of 'and' and 'or'; short ambiguous forms are treated separately.
FOREIGN_COORDINATORS = frozenset({
    ' und', ' и', ' et', ' và', ' و', ' وال', ' és', ' og',
    ' och', ' oraz', ' dan', ' oder', ' ou', ' или',
})
SHORT_COORDINATORS = frozenset({' e', ' y', ' ve', 'と', 'や', '以及'})


def english_coordination(previous, penultimate):
    """Return (and, or), using the shape of what is being coordinated."""
    word = previous.strip()
    if not word:
        return 0.03, -0.28
    if word == ',':
        numeric_list = any(c.isdigit() for c in penultimate)
        return (-0.16 if numeric_list else 0.0), -0.25
    if word.endswith(','):
        return -0.16, -0.40
    if word[-1] in ')]}':
        return -0.08, -0.47
    if word[-1] in '\"\'”’`':
        return 0.15, -0.29
    if word[-1] in '$%':
        return -0.03, -0.37
    if word[-1] in '.;:!?':
        return 0.04, -0.30
    if any(c.isdigit() for c in word):
        return 0.08, -0.28
    if not any(c.isalpha() for c in word):
        return 0.10, -0.28
    if len(word) == 1:
        return 0.20, -0.20
    if not previous[0].isspace():
        return 0.53 - 0.75 / (len(word) + 1), -0.09
    if word[0].isupper():
        strength = 0.32 if len(word) == 2 else 0.41 if len(word) == 3 else 0.48
        return strength, -0.07
    return 0.53, 0.02


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, penultimate, marker, age = '', '', '', 100
    else:
        _, previous, penultimate, marker, age = carry
    token = prefix.token_strings[-1]
    word = token.strip()
    value = 0.0
    if token in (' and', ' or'):
        value = english_coordination(previous, penultimate)[word == 'or']
        if word == 'and' and marker == 'between':
            value -= 0.48 * max(0.0, min(1.0, (14 - age) / 12))
        elif (word, marker) in (('and', 'both'), ('or', 'either')):
            value -= 0.35 * max(0.0, 1 - age / 10)
    elif word in ('And', 'AND', 'and'):
        value = 0.09
    elif token == '-and':
        value = 0.51
    elif word in ('Or', 'OR'):
        value = -0.12
    elif word == 'or':
        value = -0.03
    elif token == '/or':
        value = -0.23
    elif token in FOREIGN_COORDINATORS:
        value = -0.18
    elif token in SHORT_COORDINATORS:
        value = -0.08
    elif token in ('并', '並', '，并', '或者'):
        value = -0.24
    elif token in ('或', '且', ' yet'):
        value = -0.13
    elif token in ('和', '与', ' 和', '、'):
        prior = previous.strip()
        # A multi-character unspaced word versus a single character or delimiter.
        letters = bool(prior) and prior.isalpha()
        fragment = letters and len(prior) > 1 and not previous[0].isspace()
        if token == '、':
            if any(c.isdigit() for c in prior):
                value = -0.09
            elif fragment:
                value = 0.04
        else:
            value = -0.03 if fragment else -0.13 if letters else -0.28
    if word.lower() in ('between', 'both', 'either'):
        marker, age = word.lower(), 0
    elif word.lower() in ('and', 'or', 'nor') or token.startswith('<|'):
        marker, age = '', 100
    else:
        age = min(age + 1, 100)
    return (doc, token, previous, marker, age), value

