programs.haiku:
"""Component layers.0.mlp.down_proj:1105 (layer 0 MLP, down projection).

Fires negative on a word that opens an introductory phrase or subordinate clause, i.e. a
preposition, subordinator or introductory adverb (in, for, if, when, since, perhaps,
according, through, ...), when that word directly follows a linking word (that, but, and, so,
or, because, then, whereas, though, while, also) or a comma. Strongest for openers after
that/but/so/because, and after a comma that closes a sentence-opening marker
(However, Alternatively, Thus, ...). "the" after a link or comma is moderately negative,
"the" after "and"/"or" is not. Contrastive while/although/despite after a comma or link are
only slightly negative. Everything else is 0.
"""
READS = ()

OPENERS = {" in", " for", " if", " when", " since", " perhaps", " maybe", " after", " unless",
           " instead", " according", " given", " now", " whenever", " through", " during",
           " under", " between", " without", " at", " by", " to", " on", " from", " with",
           " as", " because", " before", " let", " each", " every", " even", " many", " all",
           " any", " no", " both", " how", " what", " whatever", " assuming", " considering",
           " suppose", " here", " the", " this"}
STRONG = {" in", " for", " if", " when", " since", " perhaps", " maybe", " after", " unless",
          " instead", " according", " given", " now", " whenever", " through", " during", " under"}
CONTRAST = {" while", " although", " though", " despite", " whereas", " whilst"}
LINKS = {"that", "but", "and", "so", "or", "because", "then", "whereas", "though", "while", "also"}
STRONG_LINKS = {"that", "but", "so", "because"}
STOPS = {".", "!", "?", "\n", "\n\n", ":", ";"}
MARKERS = {"however", "alternatively", "moreover", "furthermore", "thus", "wait", "instead",
           "therefore", "consequently", "also", "indeed", "still", "yet", "now", "well",
           "finally", "example", "similarly", "otherwise", "unfortunately", "fortunately"}


def step(carry, prefix, upstream):
    if prefix.position < 2:
        return None, 0.0
    docs = prefix.document_ids
    if docs[-1] != docs[-2]:  # first token of a new document: nothing before it
        return None, 0.0
    cur = prefix.token_strings[-1]
    prev = prefix.token_strings[-2].strip().lower()
    same2 = docs[-1] == docs[-3]  # the word before prev, if still in this document
    prev2 = prefix.token_strings[-3].strip().lower() if same2 else ""
    if cur in CONTRAST:
        return None, (-0.4 if (prev == "," or prev in LINKS) else 0.0)
    if cur not in OPENERS:
        return None, 0.0
    strong = cur in STRONG
    if prev in LINKS:
        if cur == " the":
            if prev in ("and", "or"):
                return None, 0.0
            return None, (-0.6 if prev in STRONG_LINKS else -0.4)
        if prev in STRONG_LINKS:
            return None, (-2.0 if strong else -0.9)
        return None, (-1.3 if strong else -0.6)
    if prev == ",":
        if cur == " the":
            return None, (-0.75 if prev2 in MARKERS else -0.2)
        if prev2 in MARKERS:
            return None, (-1.5 if strong else -1.0)
        return None, (-0.65 if strong else -0.3)
    if prev in STOPS and strong:
        return None, -0.6
    return None, 0.0

"""Lexicon program for layers.0.mlp.down_proj:1106 (a weak, conceptual guess).

The component's activation is mostly token-specific and idiosyncratic. The few
concepts we could see are:
  * school / homework / lesson vocabulary (English and Chinese) -> mildly positive
  * abstract "resource / activity / opportunity / ability" nouns -> mildly negative
  * Chinese characters in general -> a tiny positive offset
Each token gets its group's typical activation. Everything else gets 0.
The values were fitted by least squares on about 2,000 training positions.
"""

READS = ()

SCHOOL_WORDS = {
    "homework", "worksheet", "lesson", "attendance", "handwriting",
    "assignments", "notes", "作业", "课", "上课", "布置", "教学", "学习", "学生", "效果",
}
ABSTRACT_NOUNS = {
    "resources", "resource", "activities", "activity", "opportunity",
    "opportunities", "ability", "access", "skills", "资源", "活动", "机会", "能力",
}
SCHOOL_VALUE = 0.097
ABSTRACT_VALUE = -0.046
CJK_VALUE = 0.0025
BASE = 0.0007


def _is_cjk(text):
    return any("一" <= ch <= "鿿" for ch in text)


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    if word in SCHOOL_WORDS:
        value = SCHOOL_VALUE
    elif word in ABSTRACT_NOUNS:
        value = ABSTRACT_VALUE
    elif _is_cjk(word):
        value = CJK_VALUE
    else:
        value = 0.0
    return carry, BASE + value

programs.sol:
"""Negative 'be' spelling response, gated by the surrounding verb phrase.

Bare be is strongly negative. Modals and many infinitival constructions
attenuate it; 'seems/appears to be' reverses its sign. Smaller responses
cover been, short be-like fragments, and a few other-language be forms.
Four preceding token strings are retained, resetting at each document.
Most tokens receive zero; this does not model their small background noise.
"""
READS = ()

MODALS = {
    'can': -0.08, 'will': 0.11, 'would': 0.22, 'may': 0.43,
    'should': 0.26, 'must': 0.23, 'could': 0.09,
    'might': 0.35, 'shall': -0.09,
}
APPEARANCE = {'seem', 'seems', 'seemed', 'seeming',
              'appear', 'appears', 'appeared', 'appearing'}
NECESSITY = {'need', 'needs', 'needed', 'have', 'has', 'had', 'going',
             'likely', 'supposed', 'tend', 'tends', 'tended', 'ought'}
EVIDENCE = {'found', 'considered', 'shown', 'assumed', 'proven', 'estimated',
            'known', 'thought', 'believed', 'claimed', 'claims', 'seen',
            'prove', 'proved', 'proves', 'presumed', 'speculated', 'deemed',
            'taken', 'happen', 'happens', 'happened', 'said', 'determined'}
PERSONAL = {'i', 'we', 'you', 'he', 'she', 'they', 'who', 'what'}
DEMONSTRATIVE = {'it', 'this', 'that', 'which', 'these', 'those'}
MODIFIERS = {
    'not', 'also', 'only', 'always', 'never', 'still', 'then', 'ever', 'even',
    'now', 'well', 'indeed', 'either', 'both', 'each', 'all', 'first', 'soon',
    'already', 'again', 'therefore', 'sometimes', 'often', 'seldom', 'likewise',
    'otherwise', 'very', 'almost', 'together', 'later', 'instead', 'best',
}
FUTURE_CONTRACTIONS = {"'ll", '’ll', "'d", '’d'}
NEGATIVE_CONTRACTIONS = {"'t", '’t'}
BE_FORMS = {'être': -0.58, 'été': -0.48, 'sein': -0.63}
BE_SYLLABLES = {'ベ', '베'}
BI_SYLLABLES = {'ビ', '비'}


def modifier(word):
    return word in MODIFIERS or word.endswith('ly')


def bare_be(token, history):
    words = [s.lower() for s in history]
    last = words[-1] if words else ''
    before = words[-2] if len(words) > 1 else ''
    if token != ' be':
        if token.strip() == 'Be':
            return -4.95
        if token.strip() == 'BE':
            return -1.0 if last in MODALS or last == 'to' else -3.1
        return -3.9
    if last == 'to':
        if modifier(before) and len(words) > 2:
            before = words[-3]
        if before in APPEARANCE:
            return 1.8
        if before in NECESSITY:
            return -0.28
        if before in EVIDENCE or before == 'out':
            return 0.42
        if before in {'ready', 'waiting', 'prepare'}:
            return -2.65
        return -1.45
    if last in MODALS:
        adjustment = -0.48 if before in PERSONAL else (
            -0.25 if before in DEMONSTRATIVE else 0.07)
        if history[-1] != last:
            adjustment -= 0.65
        return MODALS[last] + adjustment
    if last == 'cannot':
        return -0.56
    if last in FUTURE_CONTRACTIONS:
        return -1.75
    if last in NEGATIVE_CONTRACTIONS:
        return -5.2 if before in {'don', 'do', 'wasn', 'isn', 'aren'} else -1.1
    if last == 'need':
        return -2.9
    if modifier(last) or last in PERSONAL | DEMONSTRATIVE | {'there'}:
        for distance, earlier in enumerate(reversed(words[:-1])):
            if earlier in MODALS:
                penalty = 2.2 if last in PERSONAL | DEMONSTRATIVE | {'there'} else (
                    0.72 if last == 'not' else 0.65)
                return MODALS[earlier] - penalty - 0.3 * distance
            if earlier in FUTURE_CONTRACTIONS | NEGATIVE_CONTRACTIONS:
                return -1.5
            if earlier in {'to', 'need'}:
                return -2.3
            if not modifier(earlier):
                break
    if last == 'gonna':
        return -0.95
    return -5.6 if last == ',' else -4.8


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    history = carry[1] if carry is not None and carry[0] == doc else ()
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    last = history[-1].lower() if history else ''
    before = history[-2].lower() if len(history) > 1 else ''
    value = 0.0
    if word == 'be':
        value = bare_be(token, history)
    elif word == 'been':
        if last == 'have':
            value = MODALS.get(before, -0.8) - 0.1
        elif last in {"'ve", '’ve', "'s", '’s'}:
            value = -1.65
        elif last in {'always', 'never'}:
            value = -0.3
        else:
            value = -0.74 if last in {'has', 'had'} else -0.9
    elif word == 'being':
        value = 0.63 if last == 'to' else -0.1
    elif word.startswith('beat') and len(word) <= 7:
        value = -0.25 if last in MODALS or last == 'to' else -0.95
    elif len(word) == 3 and word.endswith('be'):
        value = -1.4 if word[0].isalpha() else (-2.7 if word[0] == '-' else -4.1)
    elif word.startswith('be') and len(word) == 3:
        value = -0.3 if word[-1] in 'nrtg' else (0.0 if word[-1] == 'd' else -0.95)
    elif word in BE_FORMS:
        value = BE_FORMS[word]
    elif word in BE_SYLLABLES:
        value = -3.2
    elif word in BI_SYLLABLES:
        value = -1.1
    return (doc, (history + (token.strip(),))[-4:]), float(value)

programs.haiku:
"""Layer-0 MLP down-projection component 1107: a "be" detector.

The component is strongly negative on the word "be" (" be", "be", " Be", "Be", " BE",
"BE") and on "be" glued to a hyphen, slash or dot ("-be", "/be", ".be"). What it
writes depends on what comes just before "be":
- right after a modal verb (can, will, would, should, must, may, might, could, shall):
  about 0; with an adverb in between ("would indeed be") a little negative;
- after "to": "seem/appear/found/assume to be" give a positive value, other "to be"
  a moderate negative one;
- after "not", "never", "n't" and similar: moderately negative;
- otherwise (after a noun, comma, conjunction, article, pronoun, ...): strongly negative.
" been" is moderately negative. Everything else is 0.
"""

READS = ()

MODALS = {" can", " will", " would", " should", " must", " may", " might", " could",
          " shall", "will", "Can", "Will", "Must", "Should", "May", " Can", " Will"}
RAISING = {" seem", " seems", " appear", " appears", " found", " assumed", " considered",
           " shown", " believed", " thought", " known", " proved", " seen", " expected"}
NEG_ADV = {" not", " also", " only", " always", " never", " still", " then", " cannot",
           "'t", "’t", "'ll", "’ll", " even", " just", " yet", " well", " now"}
BE_WORDS = {" be", "be", " Be", "Be", " BE", "BE", "-be", "/be", ".be"}


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    if tok in BE_WORDS:
        # the words just before "be", nearest first, stopping at a document change
        before = []
        for i in range(2, 5):
            if len(prefix) < i or prefix.document_ids[-i] != prefix.document_ids[-1]:
                break
            before.append(prefix.token_strings[-i])
        prev = before[0] if before else ""
        if prev in MODALS:
            return carry, 0.0
        if any(w in MODALS for w in before[1:]):
            return carry, -0.6
        if prev == " to":
            prev2 = before[1] if len(before) > 1 else ""
            return carry, 1.0 if prev2 in RAISING else -0.7
        if prev in NEG_ADV:
            return carry, -0.7
        return carry, -4.5
    if tok in (" been", "been"):
        return carry, -0.75
    return carry, 0.0

