    'e': -0.88, 'es': -0.74, 'ed': -1.25, 'ing': -1.17,
    'en': -1.89, 'er': -1.83, 'ers': -1.37,
}


def response(token):
    original = token.strip()
    word = original.lower().lstrip('._-/(')
    spaced = token[:1].isspace()
    capitalized = original[:1].isupper()
    plain = ''.join(c for c in unicodedata.normalize('NFD', word)
                    if not unicodedata.combining(c))
    accent_scale = 0.55 if plain != word else 1.0
    word = plain

    if word in VERBS:
        value = VERBS[word]
        if capitalized and word.startswith('mak'):
            value -= 0.20
        if capitalized and word == 'taken':
            value -= 0.60
        return value * (0.75 if original.startswith('-') else 1.0)
    if word == 'ak':
        if spaced:
            value = -2.65 if capitalized else -2.20
        else:
            value = -2.60 if capitalized and not original.isupper() else -3.50
        return value * accent_scale
    if re.fullmatch('[' + CONSONANTS + ']{1,2}ak', word):
        return (-3.14 if len(word) == 3 else -1.60) * accent_scale
    if word == 'ак':
        return -2.15 if spaced else -2.92
    if word == 'как':
        return -2.12 if capitalized else -1.51
    if word == 'так':
        return -2.40
    if re.fullmatch('[' + CYRILLIC_CONSONANTS + ']ак', word):
        return -1.43
    if word.startswith('ak') and len(word) <= 5:
        if spaced:
            return -0.65
        return AK_SUFFIXES.get(word[2:], -1.50) * accent_scale
    if word.startswith('ак') and len(word) <= 4:
        return -0.85
    if word.startswith(('maker', 'baker')):
        return -1.70 if word.endswith('er') else -1.35
    if word in {'lake', 'lakes', 'oak', 'oaks'}:
        return -1.0
    if word in {'actor', 'actors'}:
        return -0.82 if word == 'actor' else -0.62
    if re.fullmatch('[' + CONSONANTS + ']?[eiou]k', word):
        if len(word) == 3:
            return -0.45
        return {'ek': -0.21, 'ik': -0.20, 'ok': -0.08, 'uk': -0.48}[word]
    if 'ak' in word and 'eak' not in word:
        return -0.36
    return 0.0


def step(carry, prefix, upstream):
    return None, response(prefix.token_strings[-1])

programs.haiku:
"""Layer-0 MLP down-projection component 1110: an "ak"-syllable detector.

The component reads only the current token (no state, no context). Its activation
is negative and token-driven:

- strongly negative (about -3) on tokens that are the syllable "ak" with at most
  one or two letters before it: "ak", "AK", " tak", " bak", " jak", and the
  Cyrillic "ак", " так", " как", " рак";
- moderately negative (about -1) on the verbs make / take and their forms
  ("make", " making", " made", " take", " taken", " took", " takes", ...);
- weakly negative (about -0.8) on other tokens containing "ak" ("aker", "akt",
  "Dakota", "Baker") but not on "eak" words (break, speak, weak, peak);
- zero on everything else.

The values are the mean activations of these token groups in the training text.
"""

MAKE_TAKE = {
    "make", "makes", "making", "maker", "makers", "made", "makeup",
    "take", "takes", "taking", "taker", "taken", "took",
}  # fmt: skip

CYRILLIC_AK = 2.0   # magnitude for Cyrillic "ак" words
SHORT_AK = 3.2      # magnitude for Latin "ak" syllables
MAKE_TAKE_MAG = 1.0
OTHER_AK_MAG = 0.8


def _is_cyrillic(s):
    return any("Ѐ" <= ch <= "ӿ" for ch in s)


def activation(token):
    s = token.strip().lower()
    if _is_cyrillic(s):
        # Cyrillic "ак" and short words ending in it: ак, так, как, рак, зак.
        return -CYRILLIC_AK if s.endswith("ак") and len(s) <= 4 else 0.0
    if s in MAKE_TAKE:
        return -MAKE_TAKE_MAG
    if len(s) <= 4 and s.endswith("ak"):
        return -SHORT_AK
    if "ak" in s and "eak" not in s:
        return -OTHER_AK_MAG
    return 0.0


READS = ()


def step(carry, prefix, upstream):
    """Stateless: the activation depends only on the newest token's spelling."""
    return None, float(activation(prefix.token_strings[prefix.position]))

programs.luna:
"""A small clue-based detector for name-like words.

Capital letters and noun-introducing prepositions make a word more likely to
be a person, place, or organization; subword pieces inherit the capitalized
word's modest signal. A tool-response closing marker gets a separate signal.
"""
READS = ()

COMMON = {"The", "A", "An", "And", "But", "Or", "So", "Yet", "I",
          "He", "She", "It", "We", "They", "You", "This", "That"}
INTRODUCERS = {"of", "in", "at", "to", "from", "by", "near", "for",
               "with", "including", "called", "named", "de", "von",
               "mr", "mrs", "ms", "dr", "prof"}
TOOL_END = "</tool_response>"


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        cap_word, previous_word = False, ""
    else:
        cap_word, previous_word = carry[1], carry[2]

    starts = bool(s[:1].isspace()) or not cap_word
    word = s.lstrip()
    cap = bool(word) and word[0].isupper()
    if cap:
        cap_word = True
        value = 0.34 if previous_word.lower() in INTRODUCERS else 0.07
        if word.isupper() and len(word) > 1:
            value = 0.12
        if word in COMMON:
            value = 0.0
    elif cap_word and not starts and word and word[0].isalnum():
        value = 0.08
    else:
        cap_word = False
        value = 0.0

    if starts and word:
        previous_word = word
    if s == TOOL_END:
        value = 1.2
    return (doc, cap_word, previous_word), float(value)

programs.sol:
"""Local naming phrases, with weaker definition and relation signals.

'Known as', 'referred to as', and 'called' get the largest positive values.
Recognize naming translations, common 'as'/'to' constructions, and 'how many'.
A few prepositions after naming words instead get negative values.
Unrecognized tokens get zero.  Keep eight token strings, resetting on a
new document; no vocabulary IDs or external data are used.
"""
import re

READS = ()

# Each set is a linguistic class, not a collection of vocabulary IDs.
NAME_WORDS = (
    (1.3, {'named', 'titled', 'entitled'}),
    (3.2, {'termed', 'nicknamed'}),
    (2.1, {'dubbed'}), (1.0, {'referred', 'aka'}),
    (0.3, {'name', 'say'}), (0.55, {'denote'}),
    (4.0, {'叫', '名叫', '什么叫'}),
    (5.2, {'叫做', '称为', '稱為', '被称为', '称之为'}),
    (2.8, {'称', '稱', '呼ば'}),
    (4.4, {'简称', '簡稱'}), (2.3, {'名为', '名為'}),
    (0.7, {'名', '名称', '名稱', 'という'}),
    # Russian naming/assigning, Spanish llamar, and French appeler stems.
    (3.2, {'наз', 'llam'}), (2.3, {'appel'}),
)
AS_WORDS = (
    (2.3, {'described', 'classified', 'designated', 'named'}),
    (1.55, {'defined', 'regarded', 'identified', 'recognized'}),
    (1.1, {'such', 'same', 'expressed', 'represented'}),
    (0.9, {'serve', 'serves', 'served'}),
    (0.55, {'used', 'considered', 'seen'}),
    (3.3, {'called', 'termed', 'abbreviated'}), (1.7, {'written'}),
)
TO_WORDS = (
    (1.2, {'equal', 'equivalent'}), (1.1, {'similar', 'comparable'}),
    (0.87, {'according', 'due', 'owing'}),
    (0.72, {'related', 'compared', 'respect', 'corresponding', 'corresponds',
            'correspond', 'refer', 'refers', 'regard', 'relate', 'relates',
            'relating', 'proportional', 'belong', 'belongs', 'prior',
            'pursuant', 'parallel', 'opposed', 'identical', 'pertaining'}),
    (0.53, {'close', 'adjacent', 'relative'}),
)


def word_class(word, classes):
    for value, words in classes:
        if word in words:
            return value
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    h = carry[1] if carry is not None and carry[0] == doc else ()
    raw = prefix.token_strings[-1]
    word = raw.strip().lower()
    prev = h[-1].strip().lower() if h else ''
    recent = ''.join(h).lower()
    value = word_class(word, NAME_WORDS) if not raw.strip().isupper() else 0.0

    if word in {'called', '-called'}:
        value = 3.5
        if word == '-called':
            value = 5.0
        elif prev in {'also', 'commonly', 'sometimes'}:
            value = 5.8
        elif prev in {'is', 'are'}:
            value = 3.9
        elif prev in {'had', 'have', 'has', 'i', 'he', 'she', 'they', 'when'}:
            value = 1.8
        elif prev in {'be', 'been', 'was', 'were'}:
            value = 2.7
        elif h and not h[-1][:1].isspace() and prev.isalpha():
            value = 2.3
    elif word == 'as' and raw[:1].isspace():
        value = word_class(prev, AS_WORDS)
        if prev == 'known':
            value = 8.4 + 1.6 * bool(re.search(r'\b(also|commonly)\b', recent))
        elif recent.endswith('referred to'):
            value = 7.7 if h[-2].strip().lower() == 'referred' else 4.4
        elif re.search(r'\b(refers?|referring) to$', recent):
            value = 4.6
        elif prev == 'referred':
            value = 6.8
        elif re.search(r'\bknown (also|only|locally|today)$', recent):
            value = 6.8 if prev == 'also' else 4.8
        if raw.strip() == 'As':
            value *= 0.4
    elif word == 'to' and raw[:1].isspace():
        value = -0.96 if prev == 'known' else word_class(prev, TO_WORDS)
    elif word == 'call' and raw[:1].isspace():
        value = 1.7 if prev == 'we' else 0.6
    elif word == 'many' and prev == 'how':
        value = 0.95
    elif word == 'oted' and recent.endswith('den'):
        value = 3.35  # 'den' + 'oted'
    elif prev == 'наз' and word.startswith('ыва'):
        value = 3.5
    elif prev in {'llam', 'cham'} and word in {'ado', 'ada', 'ados', 'adas'}:
        value = 4.3 if prev == 'llam' else 2.6
    elif prev == 'appel' and word in {'é', 'és', 'ée', 'ées'}:
        value = 3.0
    elif word == 'como' and re.search(r'\b(conocid|conhecid)[oa]s?$', recent):
        value = 5.3
    elif word == 'als' and prev == 'bekannt':
        value = 6.2

    if word in {'叫', '称', '稱', '称为', '名'} and prev in {'又', '也'}:
        value += 3.0
    elif word in {'称', '稱'} and prev == '名':
        value = 1.4
    elif word in {'为', '為'} and prev in {'称', '稱'}:
        value = 6.8
    if raw[:1].isspace() and prev == 'called':
        value = {'the': 2.1, 'a': 2.0, 'it': 2.3, 'with': -1.5,
                 'on': -1.9, 'in': -1.9, 'by': -1.2, 'for': -0.6,
                 'to': -1.05, 'out': -2.3}.get(word, value)
    elif raw[:1].isspace() and prev in {'call', 'calls', 'calling'}:
        value = {'it': 2.1, 'them': 2.1, 'the': 0.9}.get(word, value)
    if raw[:1].isspace() and prev == 'known' and word in {'about', 'from'}:
        value = -2.5
    return (doc, (h + (raw,))[-8:]), float(value)

programs.haiku:
"""Naming detector for layers.0.mlp.down_proj:1114.

The component fires on the word that introduces a name or label for something:
  - naming verbs/participles: "called", "termed", "named", "dubbed", "entitled", ...
    (and their Chinese / Russian equivalents 叫, 称, 稱, наз-), strongest on "called" and "termed";
  - "as" after a verb of naming or classifying: "known as" (strongest), "referred to as",
    "such as", "described as", "defined as", "regarded as", ...;
  - "to" after words of equality or relation: "equal to", "similar to", "according to", "due to".
Everything else is predicted as 0. Only the previous token is read, so it is causal.
"""
READS = ()

# word -> typical activation when it is the current token
NAME_WORDS = {" called": 3.0, "-called": 4.0, " termed": 3.0, " named": 1.3, " dubbed": 2.5,
              " entitled": 1.5, " titled": 1.2, " referred": 1.2, " designated": 1.0, " deemed": 1.0,
              " call": 0.5, " name": 0.2, " denote": 0.5, " say": 0.3, " aka": 0.9,
              "叫": 4.5, "称": 2.7, "稱": 2.3, "наз": 3.3}

# "as" -> activation, keyed by the previous word (other "as" are 0)
AS_AFTER = {" known": 8.9, " to": 7.0, " such": 1.1, " described": 2.3, " defined": 1.5,
            " written": 1.6, " regarded": 1.6, " identified": 1.4, " expressed": 1.1,
            " represented": 1.1, " termed": 3.5, " called": 3.5, " named": 2.4, " dubbed": 2.8}

# "to" after these previous words
TO_AFTER = {" equal", " equivalent", " similar", " comparable", " according", " due", " owing",
            " related", " compared", " corresponds", " equals", " belong"}


def step(carry, prefix, upstream):
    cur = prefix.token_strings[-1]
    same_doc = len(prefix.token_ids) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    prev = prefix.token_strings[-2] if same_doc else ""
    if cur in NAME_WORDS:
        return None, NAME_WORDS[cur]
    if cur == " as":
        return None, AS_AFTER.get(prev, 0.0)
    if cur == " to" and prev in TO_AFTER:
        return None, 1.0
    return None, 0.0

programs.luna:
"""Approximate a lexical response to language that names or defines things.

The clearest signal is on “called” (including “so-called”). Smaller
responses occur on words used to describe, and on their linking phrases.
"""

READS = ()


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().casefold()
    same_document = (
        len(prefix) > 1
        and prefix.document_ids[-2] == prefix.document_ids[-1]
    )
    previous = (
        prefix.token_strings[-2].strip().casefold() if same_document else ""
    )

    if word in {"called", "叫"}:
        value = 4.2
    elif word == "-called":
        value = 5.5
    elif word == "the" and previous == "called":
        value = 1.8
    elif word in {"abbreviated", "entitled"}:
        value = 1.2
    elif word in {"written", "describe", "say", "form"}:
        value = 0.5
    elif word == "as" and previous in {
        "such", "written", "it", "used", "depicts",
    }:
        value = 0.9
    elif word == "to" and previous in {
        "according", "referring", "refers", "pertaining", "addition",
        "relative", "respect", "attributed", "compared",
    }:
        value = 0.65
    elif word == "of" and previous == "form":
        value = 0.6
    elif word == "by" and previous == "given":
        value = 0.6
    elif word in {"喊", "という"}:
        value = 0.8
    else:
        value = 0.0

    return carry, float(value)

programs.sol:
"""A partial approximation of a plural-quantity feature.

Negative pulses occur on many/few/various and on 'of' following count or
collection nouns, especially 'number of'. 'How many' and 'wide range /
variety of' strengthen these responses. Selected translated quantifiers
and split spellings are included; any/all/every/some/numbers get small
positive values. Other tokens are near zero, leaving much weaker lexical
variation unexplained. Keep two normalized token-words, preserving them
across whitespace but resetting at every document boundary.
"""
READS = ()

BROAD = {'wide', 'wider', 'diverse', 'vast', 'huge'}
MODERATE = {'broad', 'full', 'extensive', 'great', 'large'}
PLURAL_QUANTIFIERS = {'various', 'vielen', '许多', '許多', '不少',
                     'многие', 'многих', '色々', '様々な', 'いろいろ', '다양한'}
OF_GROUPS = (
    (-0.8, {'many', 'few', 'fewer', 'thousands', 'dozens', 'myriad', 'multitude'}),
    (-0.55, {'couple', 'plurality', 'array', 'diversity', 'plethora',
             'hundreds', 'millions', 'billions', 'handful'}),
    (-0.4, {'set', 'plenty', 'bunch', 'several', 'assortment'}),
    (-0.25, {'lot', 'lots', 'pair', 'quantity', 'quantities', 'count',
              'fraction', 'proportion', 'spectrum', 'subset'}),
    (-0.18, {'amount', 'list', 'series', 'group', 'collection', 'types',
             'combination', 'percentage', 'degree', 'density', 'frequency'}),
)
OF_QUANTITY = {w: v for v, words in OF_GROUPS for w in words}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    prev, before = carry[1:] if carry is not None and carry[0] == doc else ('', '')
    raw = prefix.token_strings[-1]
    w = raw.strip().strip('_-()').lower()
    if raw and raw[0].isalpha() and prev + w in {'fewer', 'fewest', 'various'}:
        w, prev = prev + w, before
    value = 0.0
    if w == 'many':
        value = -1.0
        if prev == 'how':
            value = -1.52
        elif prev in {'so', 'too'}:
            value = -1.37
        elif prev in {'as', 'the'}:
            value = -1.24
    elif w in {'few', 'fewer', 'fewest'}:
        value = -0.65 if w == 'few' else -0.96
    elif w in PLURAL_QUANTIFIERS:
        value = -0.53
    elif '各种' in w or '各種' in w:
        value = -0.63
    elif w in {'diverse', 'countless'}:
        value = -0.36
    elif w in {'any', 'every', 'numbers'}:
        value = 0.09
    elif w in {'some', 'all'}:
        value = 0.05
    elif w in {'range', 'variety', 'array'}:
        value = -0.2 if w == 'variety' else -0.04
        if prev in BROAD:
            value -= 0.64
        elif prev in MODERATE:
            value -= 0.42
    elif w == 'of':
        value = OF_QUANTITY.get(prev, -0.01)
        if prev in {'number', 'numbers'}:
            value = -1.8 if prev == 'number' else -1.07
        elif prev in {'variety', 'range', 'array'}:
            value = -1.12 if prev == 'variety' else -0.5
            if before in BROAD:
                value -= 0.5 if prev == 'variety' else 0.65
            elif before in MODERATE:
                value -= 0.15 if prev == 'variety' else 0.35
        if not raw[:1].isspace():
            value = 0.08 if value == -0.01 else value * 0.62
    elif w == 'more' and prev == 'many':
        value = -0.65
    if not raw.strip():
        return (doc, prev, before), value
    return (doc, w, prev), value

programs.haiku:
"""Quantity words: the component goes negative on the words 'many', 'few', 'various' and
the 'of' after a quantity noun ('number of', 'variety of', 'thousands of')."""

READS = ()

# How strongly a quantity word itself drives the component (activation at that word).
QUANTIFIERS = {
    "many": -1.1, "fewer": -0.95, "few": -0.65, "various": -0.55, "diverse": -0.4,
    "countless": -0.35, "numerous": -0.2, "several": -0.2,
}

# How strongly the 'of' after a quantity noun drives it ('number of' is the strongest).
OF_AFTER = {
    "number": -1.7, "numbers": -1.1, "variety": -1.2, "thousands": -0.9, "dozens": -0.8,
    "many": -0.8, "few": -0.8, "range": -0.7, "plurality": -0.6, "couple": -0.6,
    "plethora": -0.6, "array": -0.5, "hundreds": -0.5, "millions": -0.5, "handful": -0.5,
    "several": -0.5, "bunch": -0.4, "plenty": -0.4, "tens": -0.4, "set": -0.4, "lot": -0.3,
    "lots": -0.3, "series": -0.3, "quantity": -0.3, "count": -0.3, "fraction": -0.25,
}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    if prefix.position == 0 or prefix.document_ids[-2] != prefix.document_ids[-1]:
        before = ""
    else:
        before = prefix.token_strings[-2].strip().lower()
    if word == "of":
        return carry, OF_AFTER.get(before, 0.0)
    return carry, QUANTIFIERS.get(word, 0.0)

programs.sol:
"""A mixed lexical feature, approximated by familiar words and token classes.

Large responses: positive English "havoc" and Chinese sister-in-law (嫂),
negative Java Swing trailing alignment. "Cause havoc", 大嫂, and the API
call using the alignment change their magnitudes. Weaker rules cover chat
markers, calendar names, stress/repair/wellbeing words, superscripts,
and indentation. Unrecognized tokens get a near-zero background value.
This captures only a small portion of the component's total variation.
"""

import unicodedata

READS = ()

MONTHS = set(('January February March April May June July August '
              'September October November December').split())
MONTH_WORDS = {m.lower() for m in MONTHS if m != 'May'}
CHINESE_PRONOUNS = set('我你他她它您') | {
    '我们', '你们', '他们', '她们', '它们',
}

# Delimiters distinguish reasoning, messages, and tool traffic.
CHAT_MARKERS = {
    '<think>': 0.179,
    '</think>': -0.043,
    '<|im_start|>': 0.017,
    '<|im_end|>': -0.049,
    '<|endoftext|>': 0.006,
    '<tool_call>': -0.038,
    '</tool_call>': 0.031,
    '<tool_response>': -0.013,
    '</tool_response>': -0.095,
}


def response(s, recent):
    if s in CHAT_MARKERS:
        return CHAT_MARKERS[s]
    t = s.strip()
    word = t.lower()

    if word == 'havoc':
        caused = any(w.strip().lower() in {'cause', 'caused', 'causing'}
                     for w in recent[-2:])
        return 0.76 if caused else 0.64
    if t == '嫂':
        elder = bool(recent) and recent[-1].endswith('大')
        return 0.66 if elder else 0.49
    if word in {'chaos', 'turmoil', 'mayhem'}:
        return 0.37
    if word in {'stress', 'stressful', 'stressed', 'stresses', 'ptsd'}:
        return 0.21
    if word in {'absurd', 'unfair', 'ridiculous', 'wicked', 'uncomfortable'}:
        return 0.23
    if word in {'repair', 'repairs', 'repaired', 'repairing'}:
        return 0.17

    # Calendar names, unlike the modal verb "may", are negative.
    if t in MONTHS or word in MONTH_WORDS:
        return -0.073
    if word in {'full', 'whole', 'complete', 'entire', 'entirety'}:
        return -0.050
    if word in {'knowledge', 'understand', 'understanding', 'understood',
                'cognitive', 'cognition'}:
        return -0.074
    if word in {'nutrition', 'nutrient', 'nutrients', 'wellness', 'wellbeing',
                'welfare'}:
        return 0.17
    if t in CHINESE_PRONOUNS:
        return -0.082

    # Swing layout vocabulary; punctuation distinguishes API names from prose.
    if t == '.TRAILING':
        # An alignment used to construct a parallel group is less negative.
        return -0.50 if '.createParallelGroup' in recent else -0.93
    if t == '.LEADING':
        return -0.35
    if t == '.Alignment':
        return 0.25
    if t.startswith(('.addGroup', '.addGap', '.createSequentialGroup')):
        return -0.22
    if t in {'addGroup', 'addGap', 'jPanel'}:
        return -0.22
    if t in {'.swing', 'javax', '(javax'}:
        return -0.05
    if t in {'USART', 'GPIO', 'RCC'}:
        return -0.32

    if t and all('SUPERSCRIPT' in unicodedata.name(c, '') for c in t):
        return -0.037
    if t == '、':
        return 0.030
    if s.isspace():
