    "chaos", "turmoil", "havoc", "brink", "stress", "stressful", "abortion", "abortions",
    "PTSD", "unfair", "unethical", "absurd", "manslaughter", "brutality", "grievances",
    "discontent", "misdemeanor", "concussion", "righteousness", "assassination",
}
CODE_WORDS = {
    "USART", "GPIO", "noqa", "numpy", "tkinter", "multiprocessing", "Linux", "linux",
    "django", "Symfony", "getElementById", "hasOwnProperty", "readFileSync", "jPanel",
    "FileNotFoundError", "addGap", "addGroup", "addPreferredGap", "TRAILING", "LEADING",
    "toBe", "toContain", "OrderedDict", "stdout", "stderr",
}
