    (('special',), 0.85),
    (('specif', 'spect', 'speak', 'spok'), 1.25),
    (('speech', 'species', 'space', 'spot', 'spread'), 1.95),
    (('spend', 'span', 'spirit'), 3.1),
    (('spic', 'spine', 'spinal', 'spell'), 4.5),
    (('spent', 'spin', 'spouse', 'spon'), 2.3),
    (('spiritual', 'spatial', 'spring'), 1.6),
    (('split', 'sphere'), 0.7),
    (('spaci', 'spider'), 3.0),
    (('responsibil', 'respirat', 'dispens', 'suspens'), 1.7),
    (('responsib', 'workspace', 'namespace'), 0.9),
    (('inspir', 'aspir'), 2.1),
    (('espec', 'aspect'), 0.7),
    (('atmos', 'osph', 'phosph'), 0.4),
