    'bound': 5.6, 'found': 2.07, 'sound': 2.44, 'compound': 3.3,
    'pound': 3.66, 'wound': 3.3, 'round': 1.25, 'ground': 1.17,
    'mount': 1.8, 'bind': 1.07, 'border': 1.0, 'embodiment': 0.98,
    'rebound': 3.2, 'inbound': 3.5, 'outbound': 3.5, 'abound': 2.3,
    'mound': 2.75, 'hound': 4.1,
}
INFLECTION = {'': 1.0, 's': 0.82, 'ed': 0.65, 'ing': 0.7,
              'er': 0.7, 'ers': 0.75, 'ings': 0.65}
FRAGMENTS = {'oun': 2.9, 'ouns': 1.4, 'ount': 1.9, 'oud': 0.9,
