import unicodedata

READS = ()
VOWELS = 'aeiouy'
CYRILLIC = 'аеёиоуыэюяіїє'
PAIR_BONUS = {'ae': 0.65, 'oa': 0.35, 'oe': 0.35,
              'ua': 0.30, 'eu': 0.20}


