    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    previous = carry[1] if carry and carry[0] == doc else ''
    carry = (doc, token)
    # Fathatan is the Arabic vowel sign written as a doubled fatha.
    if previous.endswith('ا') and token.startswith('ً'):
        return carry, 1.18

    p, s = plain(previous), plain(token)
    a, b = p[-1:], s[:1]
    if not a or not b:
        return carry, 0.0
    if a in 'aeiou' and b in VOWELS and not p.endswith('qu'):
        value = 0.45
        if a in 'ao':
            value += 0.25
        elif a == 'u':
            value += 0.15
        value += PAIR_BONUS.get(a + b, 0.0)
        if b in 'oy':
            value -= 0.15
        value -= 0.03 * min(10, len(p.strip()))
        value -= 0.05 * min(10, len(s))
        if len(s) > 1 and s[1].isalpha() and s[1] not in VOWELS:
            value += 0.20
        else:
            value -= 0.10
        if len(token) > 1 and token.istitle():
            value -= 0.25
    elif (previous[-1:].lower() in CYRILLIC
          and token[:1].lower() in CYRILLIC):
