        a, b = previous[-1].lower(), token[0].lower()
        value = 0.70 if a in 'аоу' else 0.45
        if b in 'юя':
            value -= 0.20
        value -= 0.03 * min(10, len(p.strip()))
    else:
        value = 0.0
    return carry, max(0.0, value)

