    "thrilled", "lucky", "fortunate", "afraid", "sensitive", "prone", "vital", "clear",
    "direct", "fast", "quick", "useless", "worthwhile", "promising", "desirable", "resistant",
    "vulnerable", "proven", "appropriate", "correct", "surprised", "shocked", "keen", "lazy",
}
