STRONG_STEMS = ("consum", "cancel")               # English consume / cancel families
STRONG_CJK = ("耗", "потреб", "취소")                # Chinese 耗, Russian/Korean consumption/cancel
MEDIUM_STEMS = ("elim", "vanish", "disappear", "beyond")
MEDIUM_CJK = ("毁", "灭", "滅")
WEAK_STEMS = ("destr", "exhaust", "smoke", "poison", "divorce", "gone", "extinct",
              "combust", "erad", "dissip", "devour")
FAINT_STEMS = ("death", "kill", "murder", "suicid", "assassin", "eat", "digest", "addict",
               "abort", "drown", "toxic")
FAINTEST_STEMS = ("remov", "dispos", "delet", "waste")


