"""Approximate a separator feature: hyphens/minus signs and dialogue boundaries.

Line-initial hyphens are strongest; spaced minus signs are intermediate;
hyphens within words or numeric ranges are weaker. Arrows and double-hyphen
comments are distinguished from minus signs. Small additional responses cover
polarity words, compass directions, weekdays, and horizontal typographic marks.
Only the previous token, recent line text, and document position are retained.
"""
import math

READS = ()
BOUNDARIES = {
    '<tool_call>': 2.50, '</tool_call>': 2.94,
    '<tool_response>': 2.34, '</tool_response>': 2.57,
    '<think>': 2.36, '</think>': 2.60,
}
POLARITY = {
    'positive': 0.68, 'negative': 0.89, 'minus': 0.65,
    'positively': 0.95, 'negatively': 1.40,
    '正': 0.60, '负': 0.60, '負': 0.60,
}
DIRECTIONS = {
    'north': 0.45, 'south': 0.73, 'east': 0.46, 'west': 0.70,
    '北': 0.53, '南': 0.74, '东': 0.46, '東': 0.38, '西': 0.85,
}
WEEKDAYS = {'monday', 'tuesday', 'wednesday', 'thursday', 'friday', 'saturday'}


def punctuation(token, line, last, position):
    text, spaced, char = token.strip(), token.startswith(' '), last[-1:]
    blank = not line.strip()
    if text == '-':
        if blank:
            value = 1.95 if spaced else 2.58 + 0.46 * math.exp(-position / 55)
        elif line.endswith('@@'):
            value = 3.08  # The negative range in a unified-diff hunk header.
        elif char.isspace():
            value = 1.86 if spaced else 1.95
        elif char.isdigit():
            value = 1.27 if spaced else 0.89
        elif char.isalpha():
            value = 1.53 if spaced else 1.03 + 0.25 * ('/' in line)
        else:
            value = 1.55 if spaced else 1.65
        if '\n' in token:
            value -= 0.20 if token.count('\n') == 1 else 0.55
        return value
    if text and set(text) == {'-'}:
        return (0.65 if blank else 0.18) if len(text) == 2 else 1.20
    if text == '–':
        if blank:
            return 1.00 if spaced else 1.37
        return 0.82 if spaced else (0.18 if char.isdigit() else 0.35)
    if text == '—':
        if blank:
            return 0.20 if spaced else 0.68
        return 0.0 if spaced else -0.15
    if text in {'−', '±', '⁻'}:
        return {'−': 0.90, '±': 0.78, '⁻': 1.30}[text]
    if text.startswith('-') and text[1:].isalpha():
        return 1.78 if blank or char.isspace() else 0.05
    if '-' in text and not any(c.isalnum() for c in text):
        if '>' in text or '<' in text:
            return 0.0  # Code arrows are not minus signs.
        return 0.65 if text.startswith('-') else 1.45
    if text.rstrip('�') == 'ー':
        return 0.80 if '�' in text else 0.55
    if text == '✓':
        return 0.32 if spaced else 0.67
    if token == '\r':
        return 0.75
    return 0.0


def step(carry, prefix, upstream):
    doc, token = prefix.document_ids[-1], prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        line, last, position = '', '', 0
    else:
        _, line, last, position = carry
    word = token.strip().lower()
    value = BOUNDARIES.get(token, POLARITY.get(word, DIRECTIONS.get(word)))
    if token == '<|im_start|>':
        value = 1.10 if position == 0 else 2.12 - 0.40 * math.exp(-position / 12)
    elif token == '<|im_end|>':
        value = 2.48 if last in {'</tool_call>', '</tool_response>'} else 3.02
        value -= 0.75 * math.exp(-position / 15)
    elif word in WEEKDAYS or word == 'sunday':
        value = 0.35 if word == 'sunday' else 0.79
    if value is None:
        value = punctuation(token, line, last, position)
    line = (line + token).rsplit('\n', 1)[-1][-100:]
    return (doc, line, token, position + 1), float(value)

