SPECIAL = {"<|im_start|>", "<|im_end|>", "<tool_call>", "</tool_call>",
           "<tool_response>", "</tool_response>", "<think>", "</think>"}
# Dash-like characters: hyphen-minus, minus sign, en dash.
MINUS = {"-", "−", "–"}
# Symbols that can sit in front of a dash in a token such as '(-' or '{-'.
OPEN = "([{.\"'`,|/_^*+"


def is_dash_token(tok):
    """A token that is a dash on its own (-, ' -', '−'), or a run of dashes and symbols
    ('---', '\\-', '+-+-'). Arrows and comment markers do not count."""
    core = tok.strip().lstrip(OPEN).rstrip("\n ")
    if core in MINUS:
        return True
    return "-" in tok and not any(c.isalnum() for c in tok) and "<" not in tok and ">" not in tok


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    if tok in SPECIAL:
        return None, 2.5
    if is_dash_token(tok):
        prev = prefix.token_strings[-2] if len(prefix.token_strings) > 1 else "\n"
        if prev.endswith("\n") or prev == "":
            return None, 2.4   # a dash starting a line, e.g. a list bullet
        if prev[-1:].isdigit():
            return None, 0.9   # a dash inside a number, e.g. 2017-11
        return None, 1.2       # a dash inside or after a word or symbol
    return None, 0.0

