"""Approximate a Slavic n-spelling detector, strongest on Cyrillic н.

Short syllables and adjective endings receive large negative values.
Boundary whitespace and capitals weaken them. Earlier н letters in the
unfinished word strengthen the response. Latin n pieces are active only
within 24 tokens of distinctive Slavic diacritics. Small background rules
cover other Cyrillic endings, vowels and signs. State resets at documents.
This uses spelling, not a reconstruction of the model's computation.
"""
READS = ()

# Vowels before н, and vowels or the soft sign after it.
BEFORE_N = {'е': -3.2, 'ё': -2.6, 'а': -2.3, 'о': -1.7,
           'и': -0.8, 'у': -0.5, 'ы': -0.7, 'я': -0.8, 'э': -0.5}
AFTER_N = {'о': -2.9, 'ы': -1.9, 'а': -1.35, 'е': -1.05,
           'и': -0.8, 'у': -0.85, 'ю': -0.7, 'я': -0.55, 'ь': -1.4}
ADJECTIVE_CASES = ('ый', 'ая', 'ое', 'ые', 'ой', 'ого', 'ую',
                   'ых', 'ым', 'ыми', 'ому', 'ом')
SOFT_N_ENDINGS = ('ние', 'ния', 'нии', 'нию', 'ний', 'нием', 'ниями', 'ниях')
FUNCTION_WORDS = {'н': -1.75, 'на': -0.18, 'не': -0.52, 'но': -1.1,
                  'он': -1.4, 'она': -0.95, 'они': -0.95, 'оно': -1.05}
MODALS = {'необходимо', 'необходим', 'нужно', 'нужен', 'нужна'}
SINGLE_LETTERS = {'а': 0.4, 'у': 0.25, 'ы': 0.25, 'е': 0.1,
                  'о': -0.3, 'й': -0.15, 'ъ': 1.05, 'ь': 0.35}
SLAVIC_MARKS = set('čćďěľĺńňřŕšśťůžźżłąćę')


def nasal_piece(s):
    """Cyrillic н-bearing syllables, inflections and consonant clusters."""
    n = len(s)
    if s == 'н':
        return -2.35
    if 'нн' in s:
        return -3.3 * min(1.0, 5.0 / n)
    if s.endswith('н') and n > 1 and s[-2] in BEFORE_N:
        return BEFORE_N[s[-2]] * min(1.0, 2.0 / n)
    if (n == 3 and s[0] in BEFORE_N and s[1] == 'н'
            and s[2] in AFTER_N and s[2] != 'ь'):
        value = (BEFORE_N[s[0]] + AFTER_N[s[2]]) / 2
        return value + (0.3 if s[2] != 'о' else 0)
    if n == 2 and s.startswith('н'):
        return AFTER_N.get(s[1], -0.7)
    for ending in ADJECTIVE_CASES:
        if s.endswith('н' + ending):
            strong_case = ending in ('ое', 'ого', 'ому', 'ом', 'ым')
            value = -2.45 if strong_case else -2.0
            if ending == 'ая':
                value += 0.5
            return value * min(1.0, (len(ending) + 1) / n)
    if s.endswith('но'):
        return -2.0
    if s.endswith(('льн', 'олн', 'ясн')):
        return -1.9
    if s.endswith(SOFT_N_ENDINGS):
        return -0.75
    if s.endswith(('ность', 'ности', 'ностью', 'ностей')):
        return -0.8
    return -0.3 if s.startswith('ник') else -0.5 * s.count('н')


def cyrillic(token):
    raw = token.strip()
    s = raw.lower()
    boundary = raw != token
    if 'н' in s:
        value = nasal_piece(s)
        if boundary:
            value *= 0.3
            if s in FUNCTION_WORDS:
                value = FUNCTION_WORDS[s]
            elif s in MODALS:
                value = -1.8 if s == 'необходимо' else -1.4
            elif s == 'можно':
                value = -1.0
        if raw != s:
            value *= 0.9 if len(s) > 1 and raw.isupper() else 0.7
        return value
    if s == 'и':
        return 0.15
    if boundary:
        return 0.0
    if s in SINGLE_LETTERS:
        return SINGLE_LETTERS[s]
    if s in ('ом', 'ам', 'ат', 'ая', 'ей', 'ой', 'ью'):
        return 0.3
    if s.endswith(('ся', 'сь')):
        return -0.5
    if s.startswith(('ител', 'ск', 'ичес')) or s in ('ого', 'ому', 'ое'):
        return -0.6
    return 0.0


def latin(token):
    s = token.strip().lower()
    if 'n' not in s or len(s) > 6 or not s.isalpha():
        return 0.0
    value = -0.55
    if s in ('en', 'no', 'ne'):
        value = -1.15
    elif 'nn' in s:
        value = -1.6
    elif s.startswith(('né', 'ný')):
        value = -1.3
    elif s.startswith(('ny', 'ní')):
        value = -0.75
    elif s.endswith('ien'):
        value = -1.05
    if token != token.strip():
        value *= 0.35
        value = {'n': -0.45, 'ne': -0.48, 'na': -0.28}.get(s, value)
    return value


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, 1000, 0)
    _, age, word_n = carry
    token = prefix.token_strings[-1]
    marked = any(c.lower() in SLAVIC_MARKS for c in token)
    age = 0 if marked else age + 1
    previous_n = word_n if token and token[0].isalpha() else 0
    if any('\u0400' <= c <= '\u04ff' for c in token):
        value = cyrillic(token)
        short_or_n = 'н' in token.lower() or len(token) == 1
        value -= (0.2 if short_or_n else 0.1) * previous_n
        if len(token) == 1 and token in 'еойь':
            value -= 0.15 * previous_n ** 2
    else:
        value = latin(token) if age <= 24 else 0.0
    # Keep at most two н letters from the unfinished alphabetic word.
    word_n = previous_n if token.isalpha() else 0
    for c in reversed(token):
        if not c.isalpha():
            break
        word_n += c.lower() == 'н'
    return (doc, min(age, 1000), min(word_n, 2)), float(value)

