"""Use trailing Cyrillic word pieces as a cue for rare negative responses.

Common Slavic-looking endings recur among the component’s stronger responses;
this small rule captures that pattern and predicts zero for other text.
"""
import unicodedata

READS = ()

# Common endings seen on the negative side of this component's responses.
WORD_ENDINGS = (
    "ого", "его", "ыми", "ные", "ных", "ный", "ная", "ное",
    "ной", "ном", "енные", "енный", "енных", "енное", "ению",
    "ение", "ений", "ния", "ние", "но", "ые", "го", "он",
    "ой", "ие", "ся", "ми", "на", "ия",
)


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        tail = ""
    else:
        tail = carry[1]

    # Start a new word after whitespace, otherwise extend the current fragment.
    if any(ch.isspace() for ch in token):
        pieces = token.split()
        fragment = pieces[-1] if pieces else ""
    else:
        fragment = tail + token
    fragment = fragment[-32:]

    # Ignore trailing punctuation; retain the final run of letters.
    end = len(fragment)
    while end and not fragment[end - 1].isalpha():
        end -= 1
    start = end
    while start and fragment[start - 1].isalpha():
        start -= 1
    word = fragment[start:end]
    is_cyrillic = bool(word) and all("CYRILLIC" in unicodedata.name(ch, "") for ch in word)

    if is_cyrillic and word.endswith(WORD_ENDINGS):
        value = -0.9
    elif is_cyrillic and word.endswith("н"):
        value = -1.2
    else:
        value = 0.0
    return (doc, fragment), float(value)

programs.sol:
"""Approximate a detector of names in markup and escape sequences.

Separately tokenized closing formatting tags are strong cues; opening tags,
HTML entities, XML declarations, LaTeX fragments and Rust references also fire.
Redacted email addresses get a large response; log labels and C++ stream
terminators have weaker rules. Other tokens return zero.
Only the last 80 characters are retained, resetting at document boundaries.
Shared constants deliberately omit token-specific and longer-context effects.
"""
import re
from html.entities import name2codepoint

READS = ()
HTML = set('a b i u s p div br hr li ul ol dl dt dd pre tt table tr td th '
           'thead tbody tfoot html head body script style title img input label '
           'option select button form template h font span em strong code sub '
           'sup small abbr'.split())
DOC_TAGS = {'summary', 'param', 'returns', 'exception', 'remarks', 'see'}
ENTITY_PREFIXES = {name[:i] for name in name2codepoint
                   for i in range(2, len(name) + 1)}
COMMANDS = set('mathbf mathbb mathcal mathfrak mathrm mathit mathsf mathtt '
               'textbf textit textup boldsymbol overline underline dagger '
               'ldots cdots vdots ddots mbox hphantom phantom nonumber '
               'backslash operatorname widetilde tilde nolimits ensuremath '
               'displaystyle textstyle'.split())
TAG = re.compile(r'<([/!?]?)([A-Za-z][A-Za-z0-9:_-]*)?$')
LATEX = re.compile(r'\\([A-Za-z]*)$')
ENV = re.compile(r'\\(begin|end)\{([A-Za-z]*)$')
ENTITY = re.compile(r'&(?:amp;)?(#x?[0-9A-Fa-f]*|[A-Za-z]*)$')


def tag_strength(name, closing):
    if name in {'code', 'strong', 'sub', 'sup', 'issue'}:
        return 4.6 if closing else 2.6
    if name in {'span', 'em'}:
        return 3.5 if closing else 1.7
    if name in {'td', 'th', 'table', 'li', 'font', 'template', 'body', 'head'}:
        return 2.6 if closing else 1.0
    if name in DOC_TAGS:
        return (2.4 if name == 'summary' else 1.1) if closing else 0.7
    if name in HTML:
        return 1.9 if closing else 0.3
    return 1.0 if closing else 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    before = carry[1] if carry is not None and carry[0] == doc else ''
    s = prefix.token_strings[-1]
    value = 0.0
    tag, latex = TAG.search(before), LATEX.search(before)
    env, entity = ENV.search(before), ENTITY.search(before)

    if re.search(r'email\s*$', before) and s.strip() == 'protected':
        value = 6.0
    elif before.rstrip().endswith(('<<', '::')) and s.strip() == 'endl':
        value = 1.4
    elif before.endswith('<![') and s in {'CDATA', 'endif'}:
        value = 2.5
    elif s.startswith('<br'):
        value = 1.0
    elif tag and s.isalnum():
        if before.endswith('\\<') and s in {'open', 'close'}:
            value = 4.4
        elif before.endswith('\\<') and s.isalpha():
            value = 2.8
        elif tag[1] == '?' and s == 'php':
            value = 1.6
        elif s in {'EMAIL', 'NAME'}:
            value = 2.8
        elif s == 'br':
            value = 2.8
        elif not tag[2]:
            value = tag_strength(s.lower(), tag[1] == '/')
            if not s.islower() and not s.isupper():
                value = 1.0 if tag[1] == '/' else 0.0
        elif tag[2] == 'h' and s.isdigit():
            value = 0.7
    elif env and s.isalpha():
        value = 1.3 if env[1] == 'end' else 0.4
    elif latex and s.isalpha():
        if not latex[1]:
            if s == 'right':
                value = 1.05
            elif s in {'left', 'text', 'mathrm', 'bold', 'bf'}:
                value = 0.45
            elif s in {'rm', 'circ', 'prime'}:
                value = 0.8
            elif s in {'math', 'frac', 'big', 'Big'}:
                value = 0.15
        elif latex[1] + s in COMMANDS or (latex[1] == 'math' and s == 'fr'):
            value = 1.0
            if s == 'symbol' or latex[1] == 'ensure':
                value = 1.95
            elif s in {'bf', 'fr', 'ilde', 'imits'}:
                value = 1.35
            elif s in {'line', 'box', 'umber', 'slash', 'style'}:
                value = 0.55
    elif entity and s.isalnum():
        name = entity[1] + s
        if name.startswith('#') and s.isdigit():
            value = 1.5 if not entity[1][1:] else 1.25
        elif name in ENTITY_PREFIXES:
            value = 3.2 if name in name2codepoint else 0.3
            if len(s) >= 3 and name not in name2codepoint:
                value = 2.1
            if s == 'quo':
                value = 4.5
            elif s in {'ld', 'rd', 'frac'}:
                value = 2.1
        elif not entity[1] and s in {'mut', 'str', 'self'}:
            value = 1.2
    elif any('&' + name in s for name in ('lt', 'gt', 'amp', 'quot', 'nbsp')):
        value = 1.9
    elif before.endswith('&mut') and s == ' self':
        value = 1.1
    elif before.endswith('span') and s == ' class':
        value = 1.1
    elif before.endswith('[') and s in {'INFO', 'WARN', 'ERROR'}:
        value = 0.65
    return (doc, (before + s)[-80:]), float(value)

