    value = WORDS.get(word, 0.0)
    if value == 0.0 and len(prefix.token_strings) > 1:
        before = prefix.token_strings[-2].strip().lower()
        if before in LEAD_IN:
            value = -0.2
    return carry, float(value)

programs.sol:
"""Token-form detector for asynchrony, anomalies, and conversation boundaries.

Async/await and sync forms are negative, as are several word stems for
abnormality or difference (including Chinese/Japanese forms). The preceding
character identifies short CJK compounds. Starting a chat message or closing
a tool response is positive. Values are approximate training averages, not a
general semantic judgment about the whole sentence.
"""
READS = ()

BOUNDARIES = {
    '<|im_start|>': 0.246,
    '</tool_response>': 0.866,
    '<|im_end|>': -0.062,
    '<tool_call>': 0.049,
    '<think>': -0.053,
}

# Different, anomalous, and unusual: individual written forms differ in strength.
DIFFERENCE_FORMS = {
    '异常': -1.84,
    '异性': -2.65,
    '差异': -1.13,
    '異なる': -0.64,
    '違い': -0.64,
    '差别': -0.39,
    '个性': -1.09,
    '个性化': -0.91,
    '各异': -1.9,
    '异地': -1.25,
    '异议': -1.8,
}


def token_value(token):
    if token in BOUNDARIES:
        return BOUNDARIES[token]
    if token in DIFFERENCE_FORMS:
        return DIFFERENCE_FORMS[token]

    word = token.strip().lstrip('._(\"').lower()
    value = -0.0014
    if word == 'async':
        value = -3.15
        if token.startswith('_'):
            value = -2.5
        elif token.startswith('('):
            value = -2.85
        elif token.startswith('.'):
            value = -2.8
    elif word in {'asynchronous', 'asynchronously'}:
        value = -2.0
    elif word in {'asyncio', 'ync'}:
        value = -0.91
    elif word == 'ynchronous':
        value = -1.14
    elif word == 'await':
        value = -0.63
        if token.startswith('.'):
            value = -0.27
        elif token.startswith('('):
            value = -0.81
    elif word == 'sync':
        value = -0.65
        if token.startswith(('_', '.')):
            value = -0.81
        elif token == ' sync':
            value = -0.53
    elif word == 'synchronous':
        value = -0.65
    elif word == 'filesync':
        value = -0.77
    elif word in {'synchron', 'synchronize', 'synchronization', 'synchronized'}:
        value = -0.3
    elif word in {'anom', 'anomal', 'anomaly', 'anomalies'}:
        value = -1.03
    elif word == 'heter':
        value = -0.97
    elif word in {'heterogeneous', 'heterosexual'}:
        value = -0.81
    elif word in {'abnormal', 'abnormalities', 'outlier', 'outliers'}:
        value = -0.56
    elif word == 'asympt':
        value = -0.68
    elif word in {'asym', 'asymmetric'}:
        value = -0.40
    elif word in {'dynamic', 'dynamics'}:
        value = -0.40 if word == 'dynamic' else -0.24
    elif word in {'exception', 'exceptions'} and token.startswith(' '):
        value = -0.36
    elif token.strip() == 'Promise':
        value = -0.35
    elif word == 'differences':
        value = -0.27
    return value


# Two-character compounds: abnormality, asynchrony, opposite sex, transfer.
CONTINUATIONS = {'常': -1.15, '步': -1.38, '性': -1.33, '動': -0.42}
WEAKER_COMPOUND_PREFIXES = frozenset('怪迥變変驚讶特相立')


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    fragmented = False
    # A byte fragment can complete a character when decoded with earlier bytes.
    if '\ufffd' in token and previous:
        text = prefix.text_prefixes[-1]
        if text.endswith(('异', '異')):
            token = text[-1]
            fragmented = True

    value = token_value(token)
    if token in {'异', '異'}:
        modifier = previous[-1:]
        if fragmented:
            value = -5.5
        elif modifier == '诧':
            value = -2.3
        elif modifier in WEAKER_COMPOUND_PREFIXES:
            value = -3.3
        else:
            value = -4.6 if token == '异' else -4.4
    elif previous in {'异', '異'} and token in CONTINUATIONS:
        value = CONTINUATIONS[token]
    return (doc, token), value

programs.luna:
"""Estimate boundary and unusualness-related lexical spikes.

The biggest repeatable positive signals are chat-control markers. A small
lexical vocabulary catches examples about anomalies and asynchronous code;
this intentionally leaves the many context-dependent small activations at zero.
"""

READS = ()

def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if token == "</tool_response>":
        return None, 0.87
    if token == "<|im_start|>":
        return None, 0.26

    word = token.strip().casefold()
    if word.startswith("async"):
        return None, -3.0
    if word.startswith("異"):
        return None, -4.5
    if word.startswith("异常"):
        return None, -2.1
    if word.startswith("heter"):
        return None, -0.8
    if word.startswith("await"):
        return None, -0.6
    if word.startswith('"sync'):
        return None, -0.55
    if word.startswith("abnormal"):
        return None, -0.55
    if word.startswith("asympt"):
        return None, -0.65
    if word.startswith("outlier"):
        return None, -0.68
    if word.startswith("違い"):
        return None, -0.7
    return None, 0.0

"""Give a small positive score to a token that is one Han ideograph."""
import unicodedata

READS = ()


def is_han(character):
    name = unicodedata.name(character, "")
    return name.startswith((
        "CJK UNIFIED IDEOGRAPH",
        "CJK COMPATIBILITY IDEOGRAPH",
    ))


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1].strip()
    if len(token) == 1 and is_han(token):
        return None, 0.27
    return None, 0.0
